-- =============================================================================
-- 0003  Research management (de-identified access only)
-- =============================================================================

create table public.research_projects (
  id                         uuid primary key default gen_random_uuid(),
  title                      text not null,
  description                text,
  specialty                  public.specialty,
  irb_reference              text,
  irb_approved_at            date,
  irb_expires_at             date,
  status                     text not null default 'draft' check (status in ('draft', 'active', 'closed')),
  principal_investigator_id  uuid not null references public.profiles (id) default auth.uid(),
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  constraint research_active_requires_irb check (
    status <> 'active' or (irb_reference is not null and irb_approved_at is not null)
  )
);

create trigger research_projects_touch before update on public.research_projects
  for each row execute function private.touch_updated_at();

create table public.research_project_members (
  project_id  uuid not null references public.research_projects (id) on delete cascade,
  user_id     uuid not null references public.profiles (id) on delete cascade,
  role        text not null default 'analyst' check (role in ('pi', 'investigator', 'analyst')),
  added_by    uuid references public.profiles (id) default auth.uid(),
  added_at    timestamptz not null default now(),
  primary key (project_id, user_id)
);

-- Enrollment links a consented patient to a project under a pseudonymous subject code.
create table public.research_enrollments (
  id                   uuid primary key default gen_random_uuid(),
  project_id           uuid not null references public.research_projects (id) on delete cascade,
  patient_id           uuid not null references public.patients (id),
  subject_code         text not null default ('S-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))),
  consent_obtained_at  timestamptz not null,
  enrolled_by          uuid references public.profiles (id) default auth.uid(),
  enrolled_at          timestamptz not null default now(),
  withdrawn_at         timestamptz,
  unique (project_id, patient_id),
  unique (project_id, subject_code)
);

create index research_enrollments_project_idx on public.research_enrollments (project_id) where withdrawn_at is null;

-- >>> 20261126000004_authorization_rls.sql
-- =============================================================================
-- 0004  Authorization helpers, integrity triggers and Row Level Security
-- =============================================================================
--
-- Access decision for a patient-scoped action `perm` (see private.patient_can):
--
--   1. Super admin                      → allowed on 'clinic' visibility records
--   2. Owning-clinic path               → visibility = 'clinic' AND the user holds
--                                         `perm` through their role in that clinic
--   3. Primary physician                → allowed if their role (in any clinic)
--                                         carries `perm`
--   4. Explicit user grant (active)     → allowed if their role carries `perm`;
--                                         write perms need access_level = 'write'
--   5. Clinic grant (active, 'clinic'   → allowed if the user holds `perm` in the
--      visibility only)                   grantee clinic; same read/write rule
--
-- 'private' records are therefore reachable only via paths 3 and 4. Super admins
-- reach them through audited break-glass (public.request_emergency_access).
-- Private encounters / documents additionally require authorship or an active
-- emergency grant.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Helper functions (SECURITY DEFINER: they read tables without recursing into
-- RLS; they only ever answer questions about the *calling* user)
-- ---------------------------------------------------------------------------
create or replace function private.is_super_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select p.is_super_admin and p.is_active from public.profiles p where p.id = auth.uid()),
    false
  );
$$;

create or replace function private.has_permission(p_clinic uuid, p_perm text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_super_admin() or exists (
    select 1
    from public.clinic_memberships m
    join public.profiles pr        on pr.id = m.user_id and pr.is_active
    join public.clinics c          on c.id = m.clinic_id and c.is_active
    join public.role_permissions rp on rp.role = m.role
    where m.user_id = auth.uid()
      and m.clinic_id = p_clinic
      and m.is_active
      and rp.permission = p_perm
  );
$$;

-- Does the user hold `perm` through ANY of their clinic roles?
create or replace function private.has_permission_any(p_perm text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_super_admin() or exists (
    select 1
    from public.clinic_memberships m
    join public.profiles pr        on pr.id = m.user_id and pr.is_active
    join public.clinics c          on c.id = m.clinic_id and c.is_active
    join public.role_permissions rp on rp.role = m.role
    where m.user_id = auth.uid()
      and m.is_active
      and rp.permission = p_perm
  );
$$;

create or replace function private.is_clinic_member(p_clinic uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_super_admin() or exists (
    select 1 from public.clinic_memberships m
    where m.user_id = auth.uid() and m.clinic_id = p_clinic and m.is_active
  );
$$;

-- Row-value variant: policies on `patients` pass the row's own columns so the
-- check works for rows being inserted in the same statement.
create or replace function private.patient_can(
  p_patient_id  uuid,
  p_clinic      uuid,
  p_visibility  public.record_visibility,
  p_primary     uuid,
  p_perm        text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := auth.uid();
  v_is_read  boolean := p_perm like '%.read';
begin
  if v_uid is null then
    return false;
  end if;

  -- 1. super admin (non-private records)
  if p_visibility = 'clinic' and private.is_super_admin() then
    return true;
  end if;

  -- 2. owning clinic
  if p_visibility = 'clinic' and private.has_permission(p_clinic, p_perm) then
    return true;
  end if;

  -- 3. primary physician
  if p_primary = v_uid and private.has_permission_any(p_perm) then
    return true;
  end if;

  -- 4. explicit user grant
  if exists (
    select 1 from public.patient_access_grants g
    where g.patient_id = p_patient_id
      and g.grantee_user_id = v_uid
      and g.revoked_at is null
      and (g.expires_at is null or g.expires_at > now())
      and (v_is_read or g.access_level = 'write')
  ) and (private.has_permission_any(p_perm) or private.is_super_admin()) then
    return true;
  end if;

  -- 5. clinic grant (only for clinic-visibility records)
  if p_visibility = 'clinic' and exists (
    select 1 from public.patient_access_grants g
    where g.patient_id = p_patient_id
      and g.grantee_clinic_id is not null
      and g.revoked_at is null
      and (g.expires_at is null or g.expires_at > now())
      and (v_is_read or g.access_level = 'write')
      and private.has_permission(g.grantee_clinic_id, p_perm)
  ) then
    return true;
  end if;

  return false;
end;
$$;

-- Id variant for child tables (encounters, documents, …).
create or replace function private.can(p_patient_id uuid, p_perm text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select private.patient_can(p.id, p.clinic_id, p.visibility, p.primary_physician_id, p_perm)
    from public.patients p
    where p.id = p_patient_id
  ), false);
$$;

create or replace function private.has_emergency_access(p_patient_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.patient_access_grants g
    where g.patient_id = p_patient_id
      and g.grantee_user_id = auth.uid()
      and g.is_emergency
      and g.revoked_at is null
      and g.expires_at > now()
  );
$$;

create or replace function private.is_project_member(p_project uuid, p_roles text[] default null)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.research_project_members m
    where m.project_id = p_project
      and m.user_id = auth.uid()
      and (p_roles is null or m.role = any (p_roles))
  );
$$;

create or replace function private.shares_clinic_with(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.clinic_memberships mine
    join public.clinic_memberships theirs on theirs.clinic_id = mine.clinic_id
    where mine.user_id = auth.uid() and mine.is_active
      and theirs.user_id = p_user
  );
$$;

create or replace function private.try_uuid(p_text text)
returns uuid
language plpgsql
immutable
set search_path = ''
as $$
begin
  return p_text::uuid;
exception when others then
  return null;
end;
$$;

-- True when the statement is executed by a server-side role (migrations,
-- service_role key, SQL editor) rather than an end user's JWT.
create or replace function private.is_server_context()
returns boolean
language sql
stable
set search_path = ''
as $$
  select current_user in ('postgres', 'service_role', 'supabase_admin');
$$;

-- ---------------------------------------------------------------------------
-- Integrity triggers (rules RLS cannot express)
-- ---------------------------------------------------------------------------

-- Only super admins may change global privilege flags.
create or replace function private.protect_profile_privileges()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if private.is_server_context() then
    return new;
  end if;
  if (new.is_super_admin is distinct from old.is_super_admin
      or new.is_active is distinct from old.is_active
      or new.id is distinct from old.id)
     and not private.is_super_admin() then
    raise exception 'Only a super administrator can change privilege or activation flags'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger profiles_protect_privileges before update on public.profiles
  for each row execute function private.protect_profile_privileges();

-- Nobody (except super admins) can create or change their own membership.
create or replace function private.protect_memberships()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_row public.clinic_memberships := coalesce(new, old);
begin
  if private.is_server_context() or private.is_super_admin() then
    return coalesce(new, old);
  end if;
  if v_row.user_id = auth.uid() or (tg_op = 'UPDATE' and old.user_id = auth.uid()) then
    raise exception 'You cannot modify your own clinic membership' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and (new.user_id <> old.user_id or new.clinic_id <> old.clinic_id) then
    raise exception 'Membership user/clinic are immutable; create a new membership' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    new.granted_by := auth.uid();
  end if;
  return coalesce(new, old);
end;
$$;

create trigger clinic_memberships_protect before insert or update or delete on public.clinic_memberships
  for each row execute function private.protect_memberships();

-- Patient record rules: owning clinic is immutable (except super admin);
-- archiving requires patient.delete; physician cannot be removed from a private record.
create or replace function private.patient_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if private.is_server_context() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.deleted_at := null;
    new.deleted_by := null;
    return new;
  end if;

  if new.clinic_id <> old.clinic_id and not private.is_super_admin() then
    raise exception 'Transferring a patient to another clinic requires a super administrator'
      using errcode = '42501';
  end if;

  if new.created_by is distinct from old.created_by or new.created_at <> old.created_at then
    raise exception 'Creation metadata is immutable' using errcode = '42501';
  end if;

  if new.deleted_at is distinct from old.deleted_at then
    if not private.patient_can(old.id, old.clinic_id, old.visibility, old.primary_physician_id, 'patient.delete') then
      raise exception 'Archiving a patient requires the patient.delete permission' using errcode = '42501';
    end if;
    new.deleted_by := case when new.deleted_at is null then null else auth.uid() end;
  end if;

  -- changing visibility / primary physician is a sharing decision
  if (new.visibility is distinct from old.visibility
      or new.primary_physician_id is distinct from old.primary_physician_id)
     and not private.patient_can(old.id, old.clinic_id, old.visibility, old.primary_physician_id, 'patient.share') then
    raise exception 'Changing record visibility or primary physician requires patient.share'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

create trigger patients_rules before insert or update on public.patients
  for each row execute function private.patient_rules();

-- Encounter signing rules.
create or replace function private.encounter_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if private.is_server_context() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.provider_id := auth.uid();
    if new.status = 'signed' then
      new.status := 'draft';
    end if;
    new.signed_at := null;
    new.signed_by := null;
    return new;
  end if;

  if old.status in ('signed', 'amended') then
    raise exception 'Signed encounters are immutable; create an amendment (amends_id) instead'
      using errcode = '42501';
  end if;

  if new.patient_id <> old.patient_id or new.provider_id <> old.provider_id then
    raise exception 'Encounter patient and provider are immutable' using errcode = '42501';
  end if;

  if new.status = 'signed' and old.status = 'draft' then
    if not private.has_permission(new.clinic_id, 'clinical.sign') then
      raise exception 'Signing requires the clinical.sign permission' using errcode = '42501';
    end if;
    new.signed_at := now();
    new.signed_by := auth.uid();
  elsif new.status <> old.status then
    raise exception 'Invalid encounter status transition % → %', old.status, new.status
      using errcode = '42501';
  end if;

  return new;
end;
$$;

create trigger encounters_rules before insert or update on public.encounters
  for each row execute function private.encounter_rules();

-- When an amendment is signed, mark the original as 'amended'.
create or replace function private.encounter_mark_amended()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.amends_id is not null and new.status = 'signed' and old.status = 'draft' then
    update public.encounters set status = 'amended'
    where id = new.amends_id and status = 'signed';
  end if;
  return new;
end;
$$;

create trigger encounters_mark_amended after update on public.encounters
  for each row execute function private.encounter_mark_amended();

-- Note: the internal 'signed' → 'amended' flip above runs as the function
-- owner, so encounter_rules() treats it as a server context and allows it.

-- Document archive rules.
create or replace function private.document_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if private.is_server_context() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.uploaded_by := auth.uid();
    new.deleted_at := null;
    new.deleted_by := null;
    return new;
  end if;
  if new.storage_path <> old.storage_path or new.patient_id <> old.patient_id
     or new.clinic_id <> old.clinic_id or new.uploaded_by <> old.uploaded_by
     or new.sha256 is distinct from old.sha256 or new.size_bytes <> old.size_bytes then
    raise exception 'Document file metadata is immutable' using errcode = '42501';
  end if;
  if new.deleted_at is distinct from old.deleted_at then
    if not private.can(old.patient_id, 'document.delete') then
      raise exception 'Archiving a document requires document.delete' using errcode = '42501';
    end if;
    new.deleted_by := case when new.deleted_at is null then null else auth.uid() end;
  end if;
  return new;
end;
$$;

create trigger documents_rules before insert or update on public.documents
  for each row execute function private.document_rules();

-- Grants: stamp grantor; emergency grants only via RPC.
create or replace function private.grant_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if private.is_server_context() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.is_emergency then
      raise exception 'Emergency access must be requested through request_emergency_access()'
        using errcode = '42501';
    end if;
    if new.grantee_user_id = auth.uid() then
      raise exception 'You cannot grant access to yourself' using errcode = '42501';
    end if;
    new.granted_by := auth.uid();
    new.granted_at := now();
    new.revoked_at := null;
    new.revoked_by := null;
    return new;
  end if;
  -- UPDATE: only revocation is allowed
  if new.patient_id <> old.patient_id
     or new.grantee_user_id is distinct from old.grantee_user_id
     or new.grantee_clinic_id is distinct from old.grantee_clinic_id
     or new.access_level <> old.access_level
     or new.is_emergency <> old.is_emergency
     or new.granted_by is distinct from old.granted_by
     or new.expires_at is distinct from old.expires_at
     or (old.revoked_at is not null) then
    raise exception 'Grants can only be revoked, not modified' using errcode = '42501';
  end if;
  if new.revoked_at is not null then
    new.revoked_at := now();
    new.revoked_by := auth.uid();
  end if;
  return new;
end;
$$;

create trigger grants_rules before insert or update on public.patient_access_grants
  for each row execute function private.grant_rules();

-- Enrollment requires recorded research consent on the patient.
create or replace function private.enrollment_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.patients p where p.id = new.patient_id and p.research_consent
  ) then
    raise exception 'Patient has not given research consent' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' and not exists (
    select 1 from public.research_projects r where r.id = new.project_id and r.status = 'active'
  ) then
    raise exception 'Patients can only be enrolled in active, IRB-approved projects' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger research_enrollments_rules before insert on public.research_enrollments
  for each row execute function private.enrollment_rules();

-- ---------------------------------------------------------------------------
-- Enable RLS everywhere
-- ---------------------------------------------------------------------------
alter table public.clinics                  enable row level security;
alter table public.profiles                 enable row level security;
alter table public.clinic_memberships       enable row level security;
alter table public.permissions              enable row level security;
alter table public.role_permissions         enable row level security;
alter table public.patients                 enable row level security;
alter table public.patient_access_grants    enable row level security;
alter table public.encounters               enable row level security;
alter table public.pregnancies              enable row level security;
alter table public.fertility_cycles         enable row level security;
alter table public.fetal_assessments        enable row level security;
alter table public.documents                enable row level security;
alter table public.research_projects        enable row level security;
alter table public.research_project_members enable row level security;
alter table public.research_enrollments     enable row level security;

-- Anonymous users get nothing.
revoke all on all tables in schema public from anon;
grant usage on schema private to authenticated;
grant execute on all functions in schema private to authenticated;

grant select, insert, update on
  public.clinics, public.profiles, public.clinic_memberships,
  public.patients, public.patient_access_grants, public.encounters, public.pregnancies,
  public.fertility_cycles, public.fetal_assessments, public.documents,
  public.research_projects, public.research_project_members, public.research_enrollments
  to authenticated;
grant delete on public.clinic_memberships, public.research_project_members to authenticated;
grant select on public.permissions, public.role_permissions to authenticated;

-- ---------------------------------------------------------------------------
-- Policies: reference data
-- ---------------------------------------------------------------------------
create policy permissions_read on public.permissions
  for select to authenticated using (true);
create policy role_permissions_read on public.role_permissions
  for select to authenticated using (true);

-- ---------------------------------------------------------------------------
-- Policies: clinics
-- ---------------------------------------------------------------------------
create policy clinics_select on public.clinics
  for select to authenticated
  using (private.is_clinic_member(id) or private.has_permission_any('patient.share'));

create policy clinics_insert on public.clinics
  for insert to authenticated
  with check (private.is_super_admin());

create policy clinics_update on public.clinics
  for update to authenticated
  using (private.has_permission(id, 'admin.clinic'))
  with check (private.has_permission(id, 'admin.clinic'));

-- ---------------------------------------------------------------------------
-- Policies: profiles
-- ---------------------------------------------------------------------------
create policy profiles_select on public.profiles
  for select to authenticated
  using (
    id = auth.uid()
    or private.is_super_admin()
    or private.shares_clinic_with(id)
    or private.has_permission_any('patient.share')   -- to pick share recipients
  );

create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = auth.uid() or private.is_super_admin())
  with check (id = auth.uid() or private.is_super_admin());

-- ---------------------------------------------------------------------------
-- Policies: clinic memberships
-- ---------------------------------------------------------------------------
create policy memberships_select on public.clinic_memberships
  for select to authenticated
  using (user_id = auth.uid() or private.is_clinic_member(clinic_id));

create policy memberships_insert on public.clinic_memberships
  for insert to authenticated
  with check (
    private.has_permission(clinic_id, 'admin.users')
    -- only super admins can appoint clinic administrators
    and (role <> 'clinic_admin' or private.is_super_admin())
  );

create policy memberships_update on public.clinic_memberships
  for update to authenticated
  using (private.has_permission(clinic_id, 'admin.users')
         and (role <> 'clinic_admin' or private.is_super_admin()))
  with check (private.has_permission(clinic_id, 'admin.users')
              and (role <> 'clinic_admin' or private.is_super_admin()));

create policy memberships_delete on public.clinic_memberships
  for delete to authenticated
  using (private.has_permission(clinic_id, 'admin.users')
         and (role <> 'clinic_admin' or private.is_super_admin()));

-- ---------------------------------------------------------------------------
-- Policies: patients
-- ---------------------------------------------------------------------------
create policy patients_select on public.patients
  for select to authenticated
  using (
    private.patient_can(id, clinic_id, visibility, primary_physician_id, 'patient.read')
    and (deleted_at is null
         or private.patient_can(id, clinic_id, visibility, primary_physician_id, 'patient.delete'))
  );

create policy patients_insert on public.patients
  for insert to authenticated
  with check (
    private.has_permission(clinic_id, 'patient.create')
    and (visibility = 'clinic' or primary_physician_id = auth.uid())
  );

create policy patients_update on public.patients
  for update to authenticated
  using (private.patient_can(id, clinic_id, visibility, primary_physician_id, 'patient.update'))
  with check (private.patient_can(id, clinic_id, visibility, primary_physician_id, 'patient.read'));
-- (no DELETE policy: patients are archived, never hard-deleted)

-- ---------------------------------------------------------------------------
-- Policies: access grants
-- ---------------------------------------------------------------------------
create policy grants_select on public.patient_access_grants
  for select to authenticated
  using (
    grantee_user_id = auth.uid()
    or granted_by = auth.uid()
    or private.can(patient_id, 'patient.share')
  );

create policy grants_insert on public.patient_access_grants
  for insert to authenticated
  with check (private.can(patient_id, 'patient.share'));

create policy grants_update on public.patient_access_grants
  for update to authenticated
  using (private.can(patient_id, 'patient.share') or granted_by = auth.uid())
  with check (private.can(patient_id, 'patient.share') or granted_by = auth.uid());

-- ---------------------------------------------------------------------------
-- Policies: encounters
-- ---------------------------------------------------------------------------
create policy encounters_select on public.encounters
  for select to authenticated
  using (
    private.can(patient_id, 'clinical.read')
    and (not is_private or provider_id = auth.uid() or private.has_emergency_access(patient_id))
  );

create policy encounters_insert on public.encounters
  for insert to authenticated
  with check (
    private.can(patient_id, 'clinical.write')
    and private.is_clinic_member(clinic_id)
  );

create policy encounters_update on public.encounters
  for update to authenticated
  using (
    private.can(patient_id, 'clinical.write')
    and (not is_private or provider_id = auth.uid())
  )
  with check (
    private.can(patient_id, 'clinical.write')
    and private.is_clinic_member(clinic_id)
  );

-- ---------------------------------------------------------------------------
-- Policies: pregnancies / fertility cycles / fetal assessments
-- ---------------------------------------------------------------------------
create policy pregnancies_select on public.pregnancies
  for select to authenticated using (private.can(patient_id, 'clinical.read'));
create policy pregnancies_insert on public.pregnancies
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy pregnancies_update on public.pregnancies
  for update to authenticated
  using (private.can(patient_id, 'clinical.write'))
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));

create policy fertility_cycles_select on public.fertility_cycles
  for select to authenticated using (private.can(patient_id, 'clinical.read'));
create policy fertility_cycles_insert on public.fertility_cycles
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy fertility_cycles_update on public.fertility_cycles
  for update to authenticated
  using (private.can(patient_id, 'clinical.write'))
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));

create policy fetal_assessments_select on public.fetal_assessments
  for select to authenticated using (private.can(patient_id, 'clinical.read'));
create policy fetal_assessments_insert on public.fetal_assessments
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy fetal_assessments_update on public.fetal_assessments
  for update to authenticated
  using (private.can(patient_id, 'clinical.write'))
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));

-- ---------------------------------------------------------------------------
-- Policies: documents
-- ---------------------------------------------------------------------------
create policy documents_select on public.documents
  for select to authenticated
  using (
    private.can(patient_id, 'document.read')
    and (not is_private or uploaded_by = auth.uid() or private.has_emergency_access(patient_id))
    and (deleted_at is null or private.can(patient_id, 'document.delete'))
  );

create policy documents_insert on public.documents
  for insert to authenticated
  with check (
    private.can(patient_id, 'document.upload')
    and exists (select 1 from public.patients p where p.id = patient_id and p.clinic_id = documents.clinic_id)
  );

create policy documents_update on public.documents
  for update to authenticated
  using (
    (uploaded_by = auth.uid() and private.can(patient_id, 'document.upload'))
    or private.can(patient_id, 'document.delete')
  )
  with check (private.can(patient_id, 'document.read'));

-- ---------------------------------------------------------------------------
-- Policies: research
-- ---------------------------------------------------------------------------
create policy research_projects_select on public.research_projects
  for select to authenticated
  using (
    private.is_super_admin()
    or principal_investigator_id = auth.uid()
    or (private.is_project_member(id) and private.has_permission_any('research.access'))
  );

create policy research_projects_insert on public.research_projects
  for insert to authenticated
  with check (private.has_permission_any('research.manage') and principal_investigator_id = auth.uid());

create policy research_projects_update on public.research_projects
  for update to authenticated
  using (principal_investigator_id = auth.uid() or private.is_super_admin())
  with check (principal_investigator_id = auth.uid() or private.is_super_admin());

create policy research_members_select on public.research_project_members
  for select to authenticated
  using (user_id = auth.uid() or private.is_project_member(project_id) or private.is_super_admin());

create policy research_members_write on public.research_project_members
  for insert to authenticated
  with check (
    private.is_super_admin()
    or exists (select 1 from public.research_projects r
               where r.id = project_id and r.principal_investigator_id = auth.uid())
  );

create policy research_members_delete on public.research_project_members
  for delete to authenticated
  using (
    private.is_super_admin()
    or exists (select 1 from public.research_projects r
               where r.id = project_id and r.principal_investigator_id = auth.uid())
  );

-- Identifiable enrollment rows are visible only to clinicians who can see the
-- patient. Researchers use public.research_cohort() (de-identified).
create policy research_enrollments_select on public.research_enrollments
  for select to authenticated
  using (private.can(patient_id, 'patient.read'));

create policy research_enrollments_insert on public.research_enrollments
  for insert to authenticated
  with check (
    private.can(patient_id, 'clinical.write')
    and private.has_permission_any('research.manage')
    and private.is_project_member(project_id, array['pi', 'investigator'])
  );

create policy research_enrollments_update on public.research_enrollments
  for update to authenticated
  using (private.can(patient_id, 'clinical.write') and private.is_project_member(project_id, array['pi', 'investigator']))
  with check (private.can(patient_id, 'clinical.write'));

-- >>> 20261126000005_audit_and_rpc.sql
-- =============================================================================
-- 0005  Append-only audit log, audit triggers and client-callable RPCs
-- =============================================================================

create table public.audit_log (
  id              bigint generated always as identity primary key,
  occurred_at     timestamptz not null default now(),
  actor_id        uuid,                       -- null = server/service context
  action          text not null check (action in (
                    'INSERT', 'UPDATE', 'DELETE',
                    'VIEW', 'DOWNLOAD', 'PRINT', 'EXPORT',
                    'EMERGENCY_ACCESS', 'RESEARCH_QUERY', 'SIGN_IN', 'SIGN_OUT')),
  table_name      text,
  record_id       uuid,
  patient_id      uuid,
  clinic_id       uuid,
  changed_fields  text[],
  old_data        jsonb,
  new_data        jsonb,
  context         jsonb not null default '{}'::jsonb
);

create index audit_log_occurred_idx on public.audit_log (occurred_at desc);
create index audit_log_patient_idx  on public.audit_log (patient_id, occurred_at desc) where patient_id is not null;
create index audit_log_clinic_idx   on public.audit_log (clinic_id, occurred_at desc);
create index audit_log_actor_idx    on public.audit_log (actor_id, occurred_at desc);

-- Append-only: block UPDATE/DELETE/TRUNCATE for everyone, including owners.
create or replace function private.audit_log_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'audit_log is append-only' using errcode = '42501';
end;
$$;

create trigger audit_log_no_update before update or delete on public.audit_log
  for each row execute function private.audit_log_immutable();
create trigger audit_log_no_truncate before truncate on public.audit_log
  for each statement execute function private.audit_log_immutable();

alter table public.audit_log enable row level security;
revoke all on public.audit_log from anon, authenticated;
grant select on public.audit_log to authenticated;

create policy audit_log_select on public.audit_log
  for select to authenticated
  using (
    private.is_super_admin()
    or (clinic_id is not null and private.has_permission(clinic_id, 'audit.read'))
  );

-- ---------------------------------------------------------------------------
-- Generic row-change audit trigger
-- ---------------------------------------------------------------------------
create or replace function private.audit_row_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old     jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  v_new     jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  v_row     jsonb := coalesce(v_new, v_old);
  v_changed text[];
  v_patient uuid;
  v_clinic  uuid;
begin
  if tg_op = 'UPDATE' then
    select array_agg(key order by key) into v_changed
    from jsonb_each(v_new) n
    where n.value is distinct from (v_old -> n.key)
      and n.key <> 'updated_at';
    if v_changed is null then
      return null;   -- no-op update, nothing to record
    end if;
  end if;

  v_patient := case
    when tg_table_name = 'patients' then (v_row ->> 'id')::uuid
    else private.try_uuid(v_row ->> 'patient_id')
  end;

  v_clinic := case
    when tg_table_name = 'clinics' then (v_row ->> 'id')::uuid
    else private.try_uuid(v_row ->> 'clinic_id')
  end;
  if v_clinic is null and v_patient is not null then
    select p.clinic_id into v_clinic from public.patients p where p.id = v_patient;
  end if;

  insert into public.audit_log
    (actor_id, action, table_name, record_id, patient_id, clinic_id, changed_fields, old_data, new_data)
  values
    (auth.uid(), tg_op, tg_table_name, private.try_uuid(v_row ->> 'id'), v_patient, v_clinic,
     v_changed, v_old, v_new);

  return null;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'clinics', 'profiles', 'clinic_memberships', 'patients', 'patient_access_grants',
    'encounters', 'pregnancies', 'fertility_cycles', 'fetal_assessments', 'documents',
    'research_projects', 'research_project_members', 'research_enrollments'
  ] loop
    execute format(
      'create trigger %I after insert or update or delete on public.%I
         for each row execute function private.audit_row_change()',
      t || '_audit', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- RPC: record read-access events (view / download / print / export)
-- ---------------------------------------------------------------------------
create or replace function public.log_access_event(
  p_action      text,
  p_patient_id  uuid,
  p_table_name  text default null,
  p_record_id   uuid default null,
  p_context     jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if p_action not in ('VIEW', 'DOWNLOAD', 'PRINT', 'EXPORT') then
    raise exception 'Unsupported access action %', p_action using errcode = '22023';
  end if;
  if not private.can(p_patient_id, 'patient.read') then
    raise exception 'No access to this patient' using errcode = '42501';
  end if;

  insert into public.audit_log (actor_id, action, table_name, record_id, patient_id, clinic_id, context)
  select auth.uid(), p_action, p_table_name, p_record_id, p.id, p.clinic_id,
         coalesce(p_context, '{}'::jsonb)
  from public.patients p where p.id = p_patient_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- RPC: break-glass emergency access (read-only, time-limited, audited)
-- ---------------------------------------------------------------------------
create or replace function public.request_emergency_access(
  p_patient_id  uuid,
  p_reason      text,
  p_hours       integer default 4
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_grant  uuid;
  v_clinic uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if p_reason is null or length(trim(p_reason)) < 15 then
    raise exception 'A clinical justification of at least 15 characters is required' using errcode = '22023';
  end if;
  if p_hours not between 1 and 24 then
    raise exception 'Emergency access may last between 1 and 24 hours' using errcode = '22023';
  end if;
  if not private.has_permission_any('clinical.read') then
    raise exception 'Emergency access is restricted to clinical staff' using errcode = '42501';
  end if;

  select clinic_id into v_clinic from public.patients where id = p_patient_id and deleted_at is null;
  if v_clinic is null then
    raise exception 'Patient not found' using errcode = 'P0002';
  end if;

  insert into public.patient_access_grants
    (patient_id, grantee_user_id, access_level, reason, is_emergency, granted_by, expires_at)
  values
    (p_patient_id, auth.uid(), 'read', trim(p_reason), true, auth.uid(), now() + make_interval(hours => p_hours))
  returning id into v_grant;

  insert into public.audit_log (actor_id, action, table_name, record_id, patient_id, clinic_id, context)
  values (auth.uid(), 'EMERGENCY_ACCESS', 'patient_access_grants', v_grant, p_patient_id, v_clinic,
          jsonb_build_object('reason', trim(p_reason), 'hours', p_hours));

  return v_grant;
end;
$$;

-- ---------------------------------------------------------------------------
-- RPC: the caller's effective access (drives UI gating; RLS stays authoritative)
-- ---------------------------------------------------------------------------
create or replace function public.get_my_access()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'user_id', p.id,
    'is_super_admin', p.is_super_admin and p.is_active,
    'is_active', p.is_active,
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'clinic_id', c.id,
        'clinic_code', c.code,
        'clinic_name_en', c.name_en,
        'clinic_name_ar', c.name_ar,
        'role', m.role,
        'permissions', (
          select coalesce(jsonb_agg(rp.permission order by rp.permission), '[]'::jsonb)
          from public.role_permissions rp where rp.role = m.role
        )
      ) order by c.name_en)
      from public.clinic_memberships m
      join public.clinics c on c.id = m.clinic_id and c.is_active
      where m.user_id = p.id and m.is_active
    ), '[]'::jsonb)
  )
  from public.profiles p
  where p.id = auth.uid();
$$;

-- ---------------------------------------------------------------------------
-- RPC: dashboard counters (SECURITY INVOKER → every count respects RLS)
-- ---------------------------------------------------------------------------
create or replace function public.dashboard_stats(p_clinic uuid default null)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'patients', (select count(*) from public.patients
                 where deleted_at is null and (p_clinic is null or clinic_id = p_clinic)),
    'active_pregnancies', (select count(*) from public.pregnancies
                 where status = 'active' and (p_clinic is null or clinic_id = p_clinic)),
    'high_risk_pregnancies', (select count(*) from public.pregnancies
                 where status = 'active' and risk_level = 'high' and (p_clinic is null or clinic_id = p_clinic)),
    'active_fertility_cycles', (select count(*) from public.fertility_cycles
                 where status not in ('completed', 'cancelled') and (p_clinic is null or clinic_id = p_clinic)),
    'fetal_assessments_30d', (select count(*) from public.fetal_assessments
                 where performed_at > now() - interval '30 days' and (p_clinic is null or clinic_id = p_clinic)),
    'encounters_today', (select count(*) from public.encounters
                 where encounter_at::date = current_date and (p_clinic is null or clinic_id = p_clinic)),
    'unsigned_encounters', (select count(*) from public.encounters
                 where status = 'draft' and provider_id = auth.uid())
  );
$$;

-- ---------------------------------------------------------------------------
-- RPC: de-identified research cohort for a project the caller belongs to
-- ---------------------------------------------------------------------------
create or replace function public.research_cohort(p_project_id uuid)
returns table (
  subject_code        text,
  age_band            text,
  blood_group         text,
  rh_factor           text,
  specialties         public.specialty[],
  pregnancies_total   bigint,
  conception_methods  text[],
  high_risk_ever      boolean,
  fertility_cycles    bigint,
  cycle_types         text[],
  fetal_assessments   bigint,
  enrolled_month      text
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if not (private.has_permission_any('research.access')
          and (private.is_project_member(p_project_id)
               or exists (select 1 from public.research_projects r
                          where r.id = p_project_id and r.principal_investigator_id = auth.uid()))) then
    raise exception 'Not a member of this research project' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.research_projects r
    where r.id = p_project_id and r.status = 'active'
      and (r.irb_expires_at is null or r.irb_expires_at >= current_date)
  ) then
    raise exception 'Project is not active or its IRB approval has expired' using errcode = '42501';
  end if;

  insert into public.audit_log (actor_id, action, table_name, record_id, context)
  values (auth.uid(), 'RESEARCH_QUERY', 'research_projects', p_project_id, '{}'::jsonb);

  return query
  select
    e.subject_code,
    -- 5-year age bands, top-coded at 50+ (k-anonymity friendly)
    case
      when date_part('year', age(e.enrolled_at::date, p.date_of_birth)) >= 50 then '50+'
      else (floor(date_part('year', age(e.enrolled_at::date, p.date_of_birth)) / 5) * 5)::int || '-'
           || ((floor(date_part('year', age(e.enrolled_at::date, p.date_of_birth)) / 5) * 5) + 4)::int
    end,
    p.blood_group,
    p.rh_factor,
    p.specialties,
    (select count(*) from public.pregnancies g where g.patient_id = p.id),
    (select array_agg(distinct g.conception) filter (where g.conception is not null)
       from public.pregnancies g where g.patient_id = p.id),
    exists (select 1 from public.pregnancies g where g.patient_id = p.id and g.risk_level = 'high'),
    (select count(*) from public.fertility_cycles f where f.patient_id = p.id),
    (select array_agg(distinct f.cycle_type) from public.fertility_cycles f where f.patient_id = p.id),
    (select count(*) from public.fetal_assessments a where a.patient_id = p.id),
    to_char(e.enrolled_at, 'YYYY-MM')
  from public.research_enrollments e
  join public.patients p on p.id = e.patient_id
  where e.project_id = p_project_id
    and e.withdrawn_at is null
    and p.research_consent
    and p.deleted_at is null;
end;
$$;

-- ---------------------------------------------------------------------------
-- Function privileges: nothing callable by anon; only intended RPCs by users
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon;
grant execute on function
  public.log_access_event(text, uuid, text, uuid, jsonb),
  public.request_emergency_access(uuid, text, integer),
  public.get_my_access(),
  public.dashboard_stats(uuid),
  public.research_cohort(uuid)
  to authenticated;

revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;

-- >>> 20261126000006_storage.sql
-- =============================================================================
-- 0006  Secure document storage
-- =============================================================================
-- Private bucket; objects are never public. Clients obtain short-lived signed
-- URLs, which Supabase only issues if the SELECT policy below allows it.
--
-- Path convention: {clinic_id}/{patient_id}/{uuid}-{sanitized-filename}
--
-- Upload flow:  1) upload object (INSERT policy checks document.upload on the
--               patient encoded in the path)  2) insert public.documents row.
-- Read flow:    SELECT on the object is allowed only if the caller can see the
--               matching public.documents row — so document-level rules
--               (is_private, archived) apply to the binary as well.
-- Objects are never updated or deleted by clients (retention); archiving is a
-- soft delete on public.documents.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'patient-documents',
  'patient-documents',
  false,
  52428800,  -- 50 MB
  array[
    'application/pdf',
    'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/tiff',
    'application/dicom',
    'text/plain',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  ]
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

create policy patient_documents_insert on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'patient-documents'
    and exists (
      select 1 from public.patients p
      where p.id = private.try_uuid((storage.foldername(name))[2])
        and p.clinic_id = private.try_uuid((storage.foldername(name))[1])
    )
    and private.can(private.try_uuid((storage.foldername(name))[2]), 'document.upload')
  );

create policy patient_documents_select on storage.objects
  for select to authenticated
  using (
    bucket_id = 'patient-documents'
    and exists (
      select 1 from public.documents d   -- evaluated under documents RLS
      where d.storage_path = storage.objects.name
    )
  );
-- No UPDATE / DELETE policies: stored clinical documents are immutable.

-- >>> 20261126000007_obstetrics.sql
-- =============================================================================
-- 0007  Obstetrics module: dating, antenatal visits, delivery & newborn records
-- =============================================================================
-- Design
--   * An antenatal visit = one `encounters` row (narrative, provider, private
--     flag, draft → signed → amended lifecycle) + one `antenatal_visits` row
--     (typed vitals for flow sheets, charts and research). Both are created
--     atomically by record_antenatal_visit(). The visit row inherits the
--     encounter's visibility and becomes read-only once the encounter is signed.
--   * Gestational age at visit / delivery is computed by the database from the
--     pregnancy's dating, so stored GA is always consistent with the EDD.
--   * Risk factors on pregnancies are coded (see src/clinical/obstetricRisk.ts).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Pregnancy dating & booking fields
-- ---------------------------------------------------------------------------
alter table public.pregnancies
  add column cycle_length_days  smallint not null default 28 check (cycle_length_days between 20 and 45),
  add column us_dating_date     date,
  add column us_dating_ga_days  smallint check (us_dating_ga_days between 35 and 200),
  add column transfer_date      date,
  add column embryo_age_days    smallint check (embryo_age_days in (3, 5, 6)),
  add column booking_date       date,
  add column booking_weight_kg  numeric(5, 1) check (booking_weight_kg between 25 and 300),
  add column height_cm          numeric(4, 1) check (height_cm between 100 and 230),
  add constraint pregnancies_gpal_consistent check (
    gravida is null or coalesce(para, 0) + coalesce(abortus, 0) <= gravida
  ),
  add constraint pregnancies_active_is_dated check (
    status <> 'active' or lmp is not null or edd is not null
  ),
  add constraint pregnancies_us_dating_pair check (
    (us_dating_date is null) = (us_dating_ga_days is null)
  ),
  add constraint pregnancies_transfer_pair check (
    transfer_date is null or embryo_age_days is not null
  );

-- One ongoing pregnancy per patient.
create unique index pregnancies_one_active_per_patient
  on public.pregnancies (patient_id) where status = 'active';

-- Registering a pregnancy tags the patient with the obstetrics specialty, so
-- she appears in specialty lists without a separate demographics edit.
create or replace function private.pregnancy_tag_patient()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.patients
     set specialties = array_append(specialties, 'obstetrics'::public.specialty)
   where id = new.patient_id and not ('obstetrics' = any (specialties));
  return new;
end;
$$;

create trigger pregnancies_tag_patient after insert on public.pregnancies
  for each row execute function private.pregnancy_tag_patient();

-- GA (days) of a pregnancy on a given date: EDD-based when available (final
-- dating), otherwise LMP adjusted for cycle length.
create or replace function private.pregnancy_ga_days(p_pregnancy uuid, p_on date)
returns smallint
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when g.edd is not null then (280 - (g.edd - p_on))::smallint
    when g.lmp is not null then ((p_on - g.lmp) - (g.cycle_length_days - 28))::smallint
  end
  from public.pregnancies g
  where g.id = p_pregnancy;
$$;

create or replace function private.encounter_status(p_encounter uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select status from public.encounters where id = p_encounter;
$$;

-- ---------------------------------------------------------------------------
-- Antenatal visits (flow sheet)
-- ---------------------------------------------------------------------------
create table public.antenatal_visits (
  id                 uuid primary key default gen_random_uuid(),
  pregnancy_id       uuid not null references public.pregnancies (id),
  patient_id         uuid not null references public.patients (id),
  clinic_id          uuid not null references public.clinics (id),
  encounter_id       uuid not null unique references public.encounters (id),
  visit_date         date not null default current_date,
  ga_days            smallint check (ga_days between 0 and 315),
  weight_kg          numeric(5, 1) check (weight_kg between 25 and 300),
  bp_systolic        smallint check (bp_systolic between 50 and 260),
  bp_diastolic       smallint check (bp_diastolic between 30 and 180),
  pulse              smallint check (pulse between 30 and 220),
  urine_protein      text check (urine_protein in ('negative', 'trace', '1+', '2+', '3+', '4+')),
  urine_glucose      text check (urine_glucose in ('negative', 'trace', '1+', '2+', '3+', '4+')),
  fundal_height_cm   numeric(4, 1) check (fundal_height_cm between 5 and 50),
  fetal_heart_rate   smallint check (fetal_heart_rate between 60 and 240),
  presentation       text check (presentation in ('cephalic', 'breech', 'transverse', 'oblique', 'unstable', 'not_assessed')),
  fetal_movements    text check (fetal_movements in ('normal', 'reduced', 'absent', 'not_assessed')),
  edema              text check (edema in ('none', 'mild', 'moderate', 'severe')),
  hemoglobin_g_dl    numeric(4, 1) check (hemoglobin_g_dl between 3 and 20),
  notes              text,
  created_by         uuid references public.profiles (id) default auth.uid(),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint antenatal_bp_pair check (
    (bp_systolic is null) = (bp_diastolic is null)
    and (bp_systolic is null or bp_systolic > bp_diastolic)
  )
);

create index antenatal_visits_pregnancy_idx on public.antenatal_visits (pregnancy_id, visit_date);
create index antenatal_visits_patient_idx on public.antenatal_visits (patient_id);

create trigger antenatal_visits_touch before update on public.antenatal_visits
  for each row execute function private.touch_updated_at();

create or replace function private.antenatal_visit_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_preg_patient uuid;
  v_enc_patient  uuid;
  v_enc_spec     public.specialty;
begin
  select patient_id into v_preg_patient from public.pregnancies where id = new.pregnancy_id;
  if v_preg_patient is distinct from new.patient_id then
    raise exception 'Visit patient does not match the pregnancy' using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' then
    if new.pregnancy_id <> old.pregnancy_id or new.encounter_id <> old.encounter_id
       or new.patient_id <> old.patient_id then
      raise exception 'Visit links are immutable' using errcode = '42501';
    end if;
    if not private.is_server_context()
       and private.encounter_status(old.encounter_id) in ('signed', 'amended') then
      raise exception 'This visit is signed; record an amendment instead' using errcode = '42501';
    end if;
  else
    -- encounter must belong to the same patient and be obstetric
    select e.patient_id, e.specialty into v_enc_patient, v_enc_spec
    from public.encounters e where e.id = new.encounter_id;
    if v_enc_patient is distinct from new.patient_id or v_enc_spec <> 'obstetrics' then
      raise exception 'Visit must link to an obstetric encounter of the same patient' using errcode = '23514';
    end if;
    if not private.is_server_context() then
      new.created_by := auth.uid();
    end if;
  end if;

  new.ga_days := private.pregnancy_ga_days(new.pregnancy_id, new.visit_date);
  return new;
end;
$$;

create trigger antenatal_visits_rules before insert or update on public.antenatal_visits
  for each row execute function private.antenatal_visit_rules();

-- ---------------------------------------------------------------------------
-- Labour & delivery, newborns
-- ---------------------------------------------------------------------------
create table public.deliveries (
  id              uuid primary key default gen_random_uuid(),
  pregnancy_id    uuid not null unique references public.pregnancies (id),
  patient_id      uuid not null references public.patients (id),
  clinic_id       uuid not null references public.clinics (id),
  delivered_at    timestamptz not null,
  ga_days         smallint check (ga_days between 140 and 315),
  onset           text not null check (onset in ('spontaneous', 'induced', 'prelabour_cs')),
  mode            text not null check (mode in ('svd', 'vacuum', 'forceps', 'vaginal_breech', 'cs_elective', 'cs_emergency')),
  indication      text,
  anesthesia      text check (anesthesia in ('none', 'epidural', 'spinal', 'combined_spinal_epidural', 'general', 'local')),
  blood_loss_ml   integer check (blood_loss_ml between 0 and 20000),
  perineum        text check (perineum in ('intact', 'first_degree', 'second_degree', 'third_degree', 'fourth_degree', 'episiotomy', 'not_applicable')),
  complications   text[] not null default '{}',
  notes           text,
  recorded_by     uuid references public.profiles (id) default auth.uid(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint deliveries_prelabour_cs check (onset <> 'prelabour_cs' or mode in ('cs_elective', 'cs_emergency'))
);

create trigger deliveries_touch before update on public.deliveries
  for each row execute function private.touch_updated_at();

create table public.newborns (
  id              uuid primary key default gen_random_uuid(),
  delivery_id     uuid not null references public.deliveries (id) on delete cascade,
  patient_id      uuid not null references public.patients (id),   -- the mother
  clinic_id       uuid not null references public.clinics (id),
  birth_order     smallint not null default 1 check (birth_order between 1 and 8),
  sex             text check (sex in ('female', 'male', 'undetermined')),
  birth_weight_g  integer check (birth_weight_g between 200 and 7000),
  apgar_1         smallint check (apgar_1 between 0 and 10),
  apgar_5         smallint check (apgar_5 between 0 and 10),
  outcome         text not null default 'live_birth' check (outcome in ('live_birth', 'stillbirth', 'neonatal_death')),
  nicu_admission  boolean not null default false,
  notes           text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (delivery_id, birth_order)
);

create trigger newborns_touch before update on public.newborns
  for each row execute function private.touch_updated_at();

create or replace function private.delivery_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_patient uuid;
  v_status  text;
begin
  select patient_id, status into v_patient, v_status from public.pregnancies where id = new.pregnancy_id;
  if v_patient is distinct from new.patient_id then
    raise exception 'Delivery patient does not match the pregnancy' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' then
    if v_status <> 'active' then
      raise exception 'Only an ongoing pregnancy can be delivered' using errcode = '23514';
    end if;
    if not private.is_server_context() then
      new.recorded_by := auth.uid();
    end if;
  elsif new.pregnancy_id <> old.pregnancy_id or new.patient_id <> old.patient_id then
    raise exception 'Delivery links are immutable' using errcode = '42501';
  end if;
  new.ga_days := private.pregnancy_ga_days(new.pregnancy_id, new.delivered_at::date);
  return new;
end;
$$;

create trigger deliveries_rules before insert or update on public.deliveries
  for each row execute function private.delivery_rules();

-- Close the pregnancy when its delivery is recorded.
create or replace function private.delivery_close_pregnancy()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.pregnancies
     set status = 'delivered', outcome_date = new.delivered_at::date
   where id = new.pregnancy_id;
  return new;
end;
$$;

create trigger deliveries_close_pregnancy after insert on public.deliveries
  for each row execute function private.delivery_close_pregnancy();

create or replace function private.newborn_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.deliveries d where d.id = new.delivery_id and d.patient_id = new.patient_id
  ) then
    raise exception 'Newborn must belong to a delivery of the same mother' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger newborns_rules before insert or update on public.newborns
  for each row execute function private.newborn_rules();

-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------
alter table public.antenatal_visits enable row level security;
alter table public.deliveries       enable row level security;
alter table public.newborns         enable row level security;

revoke all on public.antenatal_visits, public.deliveries, public.newborns from anon;
grant select, insert, update on public.antenatal_visits, public.deliveries, public.newborns to authenticated;

-- A visit is visible only if its encounter is (inherits private-note rules).
create policy antenatal_visits_select on public.antenatal_visits
  for select to authenticated
  using (
    private.can(patient_id, 'clinical.read')
    and exists (select 1 from public.encounters e where e.id = encounter_id)
  );
create policy antenatal_visits_insert on public.antenatal_visits
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy antenatal_visits_update on public.antenatal_visits
  for update to authenticated
  using (
    private.can(patient_id, 'clinical.write')
    and exists (select 1 from public.encounters e where e.id = encounter_id)
  )
  with check (private.can(patient_id, 'clinical.write'));

create policy deliveries_select on public.deliveries
  for select to authenticated using (private.can(patient_id, 'clinical.read'));
create policy deliveries_insert on public.deliveries
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy deliveries_update on public.deliveries
  for update to authenticated
  using (private.can(patient_id, 'clinical.write'))
  with check (private.can(patient_id, 'clinical.write'));

create policy newborns_select on public.newborns
  for select to authenticated using (private.can(patient_id, 'clinical.read'));
create policy newborns_insert on public.newborns
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy newborns_update on public.newborns
  for update to authenticated
  using (private.can(patient_id, 'clinical.write'))
  with check (private.can(patient_id, 'clinical.write'));

-- ---------------------------------------------------------------------------
-- Audit
-- ---------------------------------------------------------------------------
create trigger antenatal_visits_audit after insert or update or delete on public.antenatal_visits
  for each row execute function private.audit_row_change();
create trigger deliveries_audit after insert or update or delete on public.deliveries
  for each row execute function private.audit_row_change();
create trigger newborns_audit after insert or update or delete on public.newborns
  for each row execute function private.audit_row_change();

-- ---------------------------------------------------------------------------
-- RPC: record an antenatal visit atomically (encounter + vitals)
-- SECURITY INVOKER: every insert is checked by the caller's RLS.
-- ---------------------------------------------------------------------------
create or replace function public.record_antenatal_visit(
  p_pregnancy_id  uuid,
  p_visit         jsonb,
  p_encounter     jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_preg       public.pregnancies;
  v_clinic     uuid;
  v_date       date := coalesce((p_visit ->> 'visit_date')::date, current_date);
  v_encounter  uuid;
  v_visit      uuid;
  v_row        public.antenatal_visits;
begin
  select * into v_preg from public.pregnancies where id = p_pregnancy_id;
  if not found then
    raise exception 'Pregnancy not found' using errcode = 'P0002';
  end if;
  if v_preg.status <> 'active' then
    raise exception 'Visits can only be recorded for an ongoing pregnancy' using errcode = '23514';
  end if;
  if v_date > current_date then
    raise exception 'Visit date cannot be in the future' using errcode = '22023';
  end if;
  v_clinic := coalesce(nullif(p_encounter ->> 'clinic_id', '')::uuid, v_preg.clinic_id);

  insert into public.encounters
    (patient_id, clinic_id, specialty, encounter_type, encounter_at, is_private,
     chief_complaint, assessment, plan)
  values
    (v_preg.patient_id, v_clinic, 'obstetrics', 'antenatal_visit',
     case when v_date = current_date then now() else v_date::timestamptz end,
     coalesce((p_encounter ->> 'is_private')::boolean, false),
     p_encounter ->> 'chief_complaint', p_encounter ->> 'assessment', p_encounter ->> 'plan')
  returning id into v_encounter;

  v_row := jsonb_populate_record(null::public.antenatal_visits, p_visit);
  insert into public.antenatal_visits
    (pregnancy_id, patient_id, clinic_id, encounter_id, visit_date, weight_kg, bp_systolic, bp_diastolic,
     pulse, urine_protein, urine_glucose, fundal_height_cm, fetal_heart_rate, presentation,
     fetal_movements, edema, hemoglobin_g_dl, notes)
  values
    (v_preg.id, v_preg.patient_id, v_clinic, v_encounter, v_date, v_row.weight_kg, v_row.bp_systolic,
     v_row.bp_diastolic, v_row.pulse, v_row.urine_protein, v_row.urine_glucose, v_row.fundal_height_cm,
     v_row.fetal_heart_rate, v_row.presentation, v_row.fetal_movements, v_row.edema,
     v_row.hemoglobin_g_dl, v_row.notes)
  returning id into v_visit;

  return v_visit;
end;
$$;

-- ---------------------------------------------------------------------------
-- RPC: record a delivery and its newborn(s) atomically
-- ---------------------------------------------------------------------------
create or replace function public.record_delivery(
  p_pregnancy_id  uuid,
  p_delivery      jsonb,
  p_newborns      jsonb default '[]'::jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_preg      public.pregnancies;
  v_clinic    uuid;
  v_del       public.deliveries;
  v_id        uuid;
  v_baby      jsonb;
  v_nb        public.newborns;
  v_order     smallint := 0;
begin
  select * into v_preg from public.pregnancies where id = p_pregnancy_id;
  if not found then
    raise exception 'Pregnancy not found' using errcode = 'P0002';
  end if;
  if jsonb_typeof(p_newborns) <> 'array' or jsonb_array_length(p_newborns) = 0 then
    raise exception 'At least one newborn record is required' using errcode = '22023';
  end if;
  if jsonb_array_length(p_newborns) <> v_preg.plurality then
    raise exception 'Number of newborns (%) does not match plurality (%)',
      jsonb_array_length(p_newborns), v_preg.plurality using errcode = '22023';
  end if;
  v_clinic := coalesce(nullif(p_delivery ->> 'clinic_id', '')::uuid, v_preg.clinic_id);
  v_del := jsonb_populate_record(null::public.deliveries, p_delivery);
  if v_del.delivered_at > now() then
    raise exception 'Delivery time cannot be in the future' using errcode = '22023';
  end if;

  insert into public.deliveries
    (pregnancy_id, patient_id, clinic_id, delivered_at, onset, mode, indication, anesthesia,
     blood_loss_ml, perineum, complications, notes)
  values
    (v_preg.id, v_preg.patient_id, v_clinic, v_del.delivered_at, v_del.onset, v_del.mode, v_del.indication,
     v_del.anesthesia, v_del.blood_loss_ml, v_del.perineum, coalesce(v_del.complications, '{}'), v_del.notes)
  returning id into v_id;

  for v_baby in select * from jsonb_array_elements(p_newborns) loop
    v_order := v_order + 1;
    v_nb := jsonb_populate_record(null::public.newborns, v_baby);
    insert into public.newborns
      (delivery_id, patient_id, clinic_id, birth_order, sex, birth_weight_g, apgar_1, apgar_5,
       outcome, nicu_admission, notes)
    values
      (v_id, v_preg.patient_id, v_clinic, v_order, v_nb.sex, v_nb.birth_weight_g, v_nb.apgar_1, v_nb.apgar_5,
       coalesce(v_nb.outcome, 'live_birth'), coalesce(v_nb.nicu_admission, false), v_nb.notes);
  end loop;

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Obstetric worklist (SECURITY INVOKER view → every row respects RLS)
-- ---------------------------------------------------------------------------
create view public.obstetric_worklist
with (security_invoker = true)
as
select
  g.id                 as pregnancy_id,
  g.patient_id,
  g.clinic_id,
  g.lmp,
  g.edd,
  g.edd_basis,
  g.cycle_length_days,
  g.risk_level,
  g.risk_factors,
  g.plurality,
  g.gravida,
  g.para,
  g.conception,
  p.mrn,
  p.first_name_en,
  p.last_name_en,
  p.first_name_ar,
  p.last_name_ar,
  p.date_of_birth,
  p.rh_factor,
  v.visit_date         as last_visit_date,
  v.bp_systolic        as last_bp_systolic,
  v.bp_diastolic       as last_bp_diastolic,
  v.urine_protein      as last_urine_protein,
  v.fetal_movements    as last_fetal_movements,
  (select count(*) from public.antenatal_visits x where x.pregnancy_id = g.id) as visit_count
from public.pregnancies g
join public.patients p on p.id = g.patient_id and p.deleted_at is null
left join lateral (
  select a.* from public.antenatal_visits a
  where a.pregnancy_id = g.id
  order by a.visit_date desc, a.created_at desc
  limit 1
) v on true
where g.status = 'active';

revoke all on public.obstetric_worklist from anon;
grant select on public.obstetric_worklist to authenticated;

revoke execute on function public.record_antenatal_visit(uuid, jsonb, jsonb), public.record_delivery(uuid, jsonb, jsonb)
  from public, anon;
grant execute on function public.record_antenatal_visit(uuid, jsonb, jsonb), public.record_delivery(uuid, jsonb, jsonb)
  to authenticated;
revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;

-- >>> 20261126000008_obstetrics_extended.sql
-- =============================================================================
-- 0008  Obstetrics, extended: fetal biometry & EFW, multiples, postnatal care,
--       labour observations (partogram)
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Multiples: chorionicity on the pregnancy; per-fetus FHR / presentation at visits
-- ---------------------------------------------------------------------------
alter table public.pregnancies
  add column chorionicity text check (chorionicity in ('dcda', 'mcda', 'mcma', 'tcta', 'dcta', 'mcta', 'other')),
  -- high-risk documentation (antenatal follow-up card, sections 1–2)
  add column previous_cs_count    smallint check (previous_cs_count between 0 and 10),
  add column high_risk_plan       text,
  add column current_medications  text,
  add constraint pregnancies_chorionicity_multiples check (chorionicity is null or plurality > 1),
  add constraint pregnancies_cs_le_para check (previous_cs_count is null or para is null or previous_cs_count <= para);

alter table public.antenatal_visits
  add column fhr_by_fetus smallint[] check (
    fhr_by_fetus is null or (60 <= all (fhr_by_fetus) and 240 >= all (fhr_by_fetus))
  ),
  add column presentation_by_fetus text[] check (
    presentation_by_fetus is null
    or presentation_by_fetus <@ array['cephalic', 'breech', 'transverse', 'oblique', 'unstable', 'not_assessed']
  ),
  add column next_visit_date date,
  add constraint antenatal_next_visit_after check (next_visit_date is null or next_visit_date > visit_date);

-- Re-create the visit RPC so it accepts the per-fetus fields.
create or replace function public.record_antenatal_visit(
  p_pregnancy_id  uuid,
  p_visit         jsonb,
  p_encounter     jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_preg       public.pregnancies;
  v_clinic     uuid;
  v_date       date := coalesce((p_visit ->> 'visit_date')::date, current_date);
  v_encounter  uuid;
  v_visit      uuid;
  v_row        public.antenatal_visits;
begin
  select * into v_preg from public.pregnancies where id = p_pregnancy_id;
  if not found then
    raise exception 'Pregnancy not found' using errcode = 'P0002';
  end if;
  if v_preg.status <> 'active' then
    raise exception 'Visits can only be recorded for an ongoing pregnancy' using errcode = '23514';
  end if;
  if v_date > current_date then
    raise exception 'Visit date cannot be in the future' using errcode = '22023';
  end if;
  v_clinic := coalesce(nullif(p_encounter ->> 'clinic_id', '')::uuid, v_preg.clinic_id);

  insert into public.encounters
    (patient_id, clinic_id, specialty, encounter_type, encounter_at, is_private, chief_complaint, assessment, plan)
  values
    (v_preg.patient_id, v_clinic, 'obstetrics', 'antenatal_visit',
     case when v_date = current_date then now() else v_date::timestamptz end,
     coalesce((p_encounter ->> 'is_private')::boolean, false),
     p_encounter ->> 'chief_complaint', p_encounter ->> 'assessment', p_encounter ->> 'plan')
  returning id into v_encounter;

  v_row := jsonb_populate_record(null::public.antenatal_visits, p_visit);
  insert into public.antenatal_visits
    (pregnancy_id, patient_id, clinic_id, encounter_id, visit_date, weight_kg, bp_systolic, bp_diastolic,
     pulse, urine_protein, urine_glucose, fundal_height_cm, fetal_heart_rate, presentation,
     fetal_movements, edema, hemoglobin_g_dl, notes, fhr_by_fetus, presentation_by_fetus, next_visit_date)
  values
    (v_preg.id, v_preg.patient_id, v_clinic, v_encounter, v_date, v_row.weight_kg, v_row.bp_systolic,
     v_row.bp_diastolic, v_row.pulse, v_row.urine_protein, v_row.urine_glucose, v_row.fundal_height_cm,
     v_row.fetal_heart_rate, v_row.presentation, v_row.fetal_movements, v_row.edema,
     v_row.hemoglobin_g_dl, v_row.notes, v_row.fhr_by_fetus, v_row.presentation_by_fetus, v_row.next_visit_date)
  returning id into v_visit;

  return v_visit;
end;
$$;

-- ---------------------------------------------------------------------------
-- Fetal biometry (one row per fetus per scan)
-- ---------------------------------------------------------------------------
-- Hadlock 4 (HC, AC, FL) — Hadlock FP et al., Am J Obstet Gynecol 1985;151:333.
-- log10(EFW g) = 1.326 − 0.00326·AC·FL + 0.0107·HC + 0.0438·AC + 0.158·FL  (cm)
create or replace function private.hadlock_efw(p_hc_mm numeric, p_ac_mm numeric, p_fl_mm numeric)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case when p_hc_mm is null or p_ac_mm is null or p_fl_mm is null then null
    else round(power(10, 1.326
      - 0.00326 * (p_ac_mm / 10) * (p_fl_mm / 10)
      + 0.0107 * (p_hc_mm / 10)
      + 0.0438 * (p_ac_mm / 10)
      + 0.158 * (p_fl_mm / 10)))::integer
  end;
$$;

create table public.fetal_biometry (
  id                   uuid primary key default gen_random_uuid(),
  fetal_assessment_id  uuid not null references public.fetal_assessments (id) on delete cascade,
  pregnancy_id         uuid not null references public.pregnancies (id),
  patient_id           uuid not null references public.patients (id),
  clinic_id            uuid not null references public.clinics (id),
  fetus_label          text not null default 'A' check (fetus_label in ('A', 'B', 'C', 'D', 'E', 'F', 'G', 'H')),
  ga_days              smallint check (ga_days between 0 and 315),
  crl_mm               numeric(5, 1) check (crl_mm between 1 and 100),
  bpd_mm               numeric(5, 1) check (bpd_mm between 10 and 120),
  hc_mm                numeric(5, 1) check (hc_mm between 50 and 420),
  ac_mm                numeric(5, 1) check (ac_mm between 40 and 450),
  fl_mm                numeric(5, 1) check (fl_mm between 5 and 90),
  efw_g                integer check (efw_g between 50 and 7000),
  afi_cm               numeric(4, 1) check (afi_cm between 0 and 60),
  dvp_cm               numeric(4, 1) check (dvp_cm between 0 and 25),
  ua_pi                numeric(4, 2) check (ua_pi between 0 and 5),
  ua_edf               text check (ua_edf in ('present', 'absent', 'reversed')),
  mca_pi               numeric(4, 2) check (mca_pi between 0 and 5),
  fhr                  smallint check (fhr between 60 and 240),
  presentation         text check (presentation in ('cephalic', 'breech', 'transverse', 'oblique', 'unstable', 'not_assessed')),
  placenta_location    text check (placenta_location in ('anterior', 'posterior', 'fundal', 'lateral', 'low_lying', 'previa')),
  notes                text,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (fetal_assessment_id, fetus_label)
);

create index fetal_biometry_pregnancy_idx on public.fetal_biometry (pregnancy_id, ga_days);

create trigger fetal_biometry_touch before update on public.fetal_biometry
  for each row execute function private.touch_updated_at();

create or replace function private.fetal_biometry_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_fa public.fetal_assessments;
begin
  select * into v_fa from public.fetal_assessments where id = new.fetal_assessment_id;
  if v_fa.patient_id is distinct from new.patient_id
     or (v_fa.pregnancy_id is not null and v_fa.pregnancy_id <> new.pregnancy_id) then
    raise exception 'Biometry must match its scan and pregnancy' using errcode = '23514';
  end if;
  if not exists (select 1 from public.pregnancies g where g.id = new.pregnancy_id and g.patient_id = new.patient_id) then
    raise exception 'Biometry patient does not match the pregnancy' using errcode = '23514';
  end if;
  new.ga_days := private.pregnancy_ga_days(new.pregnancy_id, v_fa.performed_at::date);
  new.efw_g := coalesce(private.hadlock_efw(new.hc_mm, new.ac_mm, new.fl_mm), new.efw_g);
  return new;
end;
$$;

create trigger fetal_biometry_rules before insert or update on public.fetal_biometry
  for each row execute function private.fetal_biometry_rules();

-- Record a scan + per-fetus biometry atomically.
create or replace function public.record_fetal_scan(
  p_pregnancy_id  uuid,
  p_scan          jsonb,
  p_fetuses       jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_preg   public.pregnancies;
  v_clinic uuid;
  v_at     timestamptz := coalesce((p_scan ->> 'performed_at')::timestamptz, now());
  v_id     uuid;
  v_f      jsonb;
  v_b      public.fetal_biometry;
begin
  select * into v_preg from public.pregnancies where id = p_pregnancy_id;
  if not found then
    raise exception 'Pregnancy not found' using errcode = 'P0002';
  end if;
  if v_at > now() then
    raise exception 'Scan date cannot be in the future' using errcode = '22023';
  end if;
  if jsonb_typeof(p_fetuses) <> 'array' or jsonb_array_length(p_fetuses) = 0
     or jsonb_array_length(p_fetuses) > v_preg.plurality then
    raise exception 'Provide between 1 and % fetus records', v_preg.plurality using errcode = '22023';
  end if;
  v_clinic := coalesce(nullif(p_scan ->> 'clinic_id', '')::uuid, v_preg.clinic_id);

  insert into public.fetal_assessments
    (patient_id, pregnancy_id, clinic_id, assessment_type, performed_at, gestational_age_days, fetus_number, impression, findings)
  values
    (v_preg.patient_id, v_preg.id, v_clinic, coalesce(p_scan ->> 'assessment_type', 'growth_scan'), v_at,
     private.pregnancy_ga_days(v_preg.id, v_at::date), jsonb_array_length(p_fetuses),
     p_scan ->> 'impression', '{}'::jsonb)
  returning id into v_id;

  for v_f in select * from jsonb_array_elements(p_fetuses) loop
    v_b := jsonb_populate_record(null::public.fetal_biometry, v_f);
    insert into public.fetal_biometry
      (fetal_assessment_id, pregnancy_id, patient_id, clinic_id, fetus_label, crl_mm, bpd_mm, hc_mm, ac_mm, fl_mm,
       efw_g, afi_cm, dvp_cm, ua_pi, ua_edf, mca_pi, fhr, presentation, placenta_location, notes)
    values
      (v_id, v_preg.id, v_preg.patient_id, v_clinic, coalesce(v_b.fetus_label, 'A'), v_b.crl_mm, v_b.bpd_mm, v_b.hc_mm,
       v_b.ac_mm, v_b.fl_mm, v_b.efw_g, v_b.afi_cm, v_b.dvp_cm, v_b.ua_pi, v_b.ua_edf, v_b.mca_pi, v_b.fhr,
       v_b.presentation, v_b.placenta_location, v_b.notes);
  end loop;

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Postnatal visits
-- ---------------------------------------------------------------------------
create table public.postnatal_visits (
  id                uuid primary key default gen_random_uuid(),
  delivery_id       uuid not null references public.deliveries (id),
  pregnancy_id      uuid not null references public.pregnancies (id),
  patient_id        uuid not null references public.patients (id),
  clinic_id         uuid not null references public.clinics (id),
  encounter_id      uuid not null unique references public.encounters (id),
  visit_date        date not null default current_date,
  days_postpartum   smallint check (days_postpartum between 0 and 365),
  bp_systolic       smallint check (bp_systolic between 50 and 260),
  bp_diastolic      smallint check (bp_diastolic between 30 and 180),
  pulse             smallint check (pulse between 30 and 220),
  temperature_c     numeric(3, 1) check (temperature_c between 34 and 43),
  uterus            text check (uterus in ('well_contracted', 'subinvolution', 'tender')),
  lochia            text check (lochia in ('normal', 'heavy', 'offensive', 'absent')),
  wound             text check (wound in ('not_applicable', 'healing', 'infection', 'dehiscence')),
  breastfeeding     text check (breastfeeding in ('exclusive', 'mixed', 'formula', 'not_feeding')),
  breasts           text check (breasts in ('normal', 'engorgement', 'mastitis', 'nipple_trauma')),
  epds_score        smallint check (epds_score between 0 and 30),
  epds_self_harm    boolean,
  hemoglobin_g_dl   numeric(4, 1) check (hemoglobin_g_dl between 3 and 20),
  contraception     text,
  notes             text,
  created_by        uuid references public.profiles (id) default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint postnatal_bp_pair check (
    (bp_systolic is null) = (bp_diastolic is null) and (bp_systolic is null or bp_systolic > bp_diastolic)
  )
);

create index postnatal_visits_delivery_idx on public.postnatal_visits (delivery_id, visit_date);

create trigger postnatal_visits_touch before update on public.postnatal_visits
  for each row execute function private.touch_updated_at();

create or replace function private.postnatal_visit_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_del public.deliveries;
begin
  select * into v_del from public.deliveries where id = new.delivery_id;
  if v_del.patient_id is distinct from new.patient_id or v_del.pregnancy_id <> new.pregnancy_id then
    raise exception 'Postnatal visit must match its delivery' using errcode = '23514';
  end if;
  if new.visit_date < v_del.delivered_at::date then
    raise exception 'Postnatal visit cannot precede the delivery' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' then
    if new.delivery_id <> old.delivery_id or new.encounter_id <> old.encounter_id then
      raise exception 'Visit links are immutable' using errcode = '42501';
    end if;
    if not private.is_server_context()
       and private.encounter_status(old.encounter_id) in ('signed', 'amended') then
      raise exception 'This visit is signed; record an amendment instead' using errcode = '42501';
    end if;
  elsif not private.is_server_context() then
    new.created_by := auth.uid();
  end if;
  new.days_postpartum := new.visit_date - v_del.delivered_at::date;
  return new;
end;
$$;

create trigger postnatal_visits_rules before insert or update on public.postnatal_visits
  for each row execute function private.postnatal_visit_rules();

create or replace function public.record_postnatal_visit(
  p_delivery_id  uuid,
  p_visit        jsonb,
  p_encounter    jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_del    public.deliveries;
  v_clinic uuid;
  v_date   date := coalesce((p_visit ->> 'visit_date')::date, current_date);
  v_enc    uuid;
  v_id     uuid;
  v_row    public.postnatal_visits;
begin
  select * into v_del from public.deliveries where id = p_delivery_id;
  if not found then
    raise exception 'Delivery not found' using errcode = 'P0002';
  end if;
  if v_date > current_date then
    raise exception 'Visit date cannot be in the future' using errcode = '22023';
  end if;
  v_clinic := coalesce(nullif(p_encounter ->> 'clinic_id', '')::uuid, v_del.clinic_id);

  insert into public.encounters
    (patient_id, clinic_id, specialty, encounter_type, encounter_at, is_private, chief_complaint, assessment, plan)
  values
    (v_del.patient_id, v_clinic, 'obstetrics', 'postnatal_visit',
     case when v_date = current_date then now() else v_date::timestamptz end,
     coalesce((p_encounter ->> 'is_private')::boolean, false),
     p_encounter ->> 'chief_complaint', p_encounter ->> 'assessment', p_encounter ->> 'plan')
  returning id into v_enc;

  v_row := jsonb_populate_record(null::public.postnatal_visits, p_visit);
  insert into public.postnatal_visits
    (delivery_id, pregnancy_id, patient_id, clinic_id, encounter_id, visit_date, bp_systolic, bp_diastolic, pulse,
     temperature_c, uterus, lochia, wound, breastfeeding, breasts, epds_score, epds_self_harm, hemoglobin_g_dl,
     contraception, notes)
  values
    (v_del.id, v_del.pregnancy_id, v_del.patient_id, v_clinic, v_enc, v_date, v_row.bp_systolic, v_row.bp_diastolic,
     v_row.pulse, v_row.temperature_c, v_row.uterus, v_row.lochia, v_row.wound, v_row.breastfeeding, v_row.breasts,
     v_row.epds_score, v_row.epds_self_harm, v_row.hemoglobin_g_dl, v_row.contraception, v_row.notes)
  returning id into v_id;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Labour observations (partogram). Append-only: an entry can only be flagged
-- "entered in error", never edited or deleted.
-- ---------------------------------------------------------------------------
create table public.labour_observations (
  id                      uuid primary key default gen_random_uuid(),
  pregnancy_id            uuid not null references public.pregnancies (id),
  patient_id              uuid not null references public.patients (id),
  clinic_id               uuid not null references public.clinics (id),
  observed_at             timestamptz not null default now(),
  cervical_dilation_cm    numeric(3, 1) check (cervical_dilation_cm between 0 and 10),
  descent_fifths          smallint check (descent_fifths between 0 and 5),
  contractions_per_10min  smallint check (contractions_per_10min between 0 and 8),
  contraction_duration_s  smallint check (contraction_duration_s between 0 and 180),
  fhr                     smallint check (fhr between 50 and 240),
  liquor                  text check (liquor in ('intact', 'clear', 'meconium_light', 'meconium_thick', 'blood_stained', 'absent')),
  moulding                smallint check (moulding between 0 and 3),
  bp_systolic             smallint check (bp_systolic between 50 and 260),
  bp_diastolic            smallint check (bp_diastolic between 30 and 180),
  pulse                   smallint check (pulse between 30 and 220),
  temperature_c           numeric(3, 1) check (temperature_c between 34 and 43),
  oxytocin_mu_min         numeric(4, 1) check (oxytocin_mu_min between 0 and 40),
  notes                   text,
  entered_in_error        boolean not null default false,
  recorded_by             uuid references public.profiles (id) default auth.uid(),
  created_at              timestamptz not null default now(),
  constraint labour_bp_pair check (
    (bp_systolic is null) = (bp_diastolic is null) and (bp_systolic is null or bp_systolic > bp_diastolic)
  )
);

create index labour_observations_pregnancy_idx on public.labour_observations (pregnancy_id, observed_at);

create or replace function private.labour_observation_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_preg public.pregnancies;
begin
  if tg_op = 'UPDATE' then
    if (to_jsonb(new) - 'entered_in_error') <> (to_jsonb(old) - 'entered_in_error') then
      raise exception 'Labour observations are append-only; mark the entry as entered in error and add a new one'
        using errcode = '42501';
    end if;
    return new;
  end if;
  select * into v_preg from public.pregnancies where id = new.pregnancy_id;
  if v_preg.patient_id is distinct from new.patient_id then
    raise exception 'Observation patient does not match the pregnancy' using errcode = '23514';
  end if;
  if v_preg.status <> 'active' then
    raise exception 'Labour observations require an ongoing pregnancy' using errcode = '23514';
  end if;
  if private.pregnancy_ga_days(v_preg.id, new.observed_at::date) < 140 then
    raise exception 'Labour observations require GA of at least 20 weeks' using errcode = '23514';
  end if;
  if new.observed_at > now() + interval '5 minutes' then
    raise exception 'Observation time cannot be in the future' using errcode = '22023';
  end if;
  if not private.is_server_context() then
    new.recorded_by := auth.uid();
    new.entered_in_error := false;
  end if;
  return new;
end;
$$;

create trigger labour_observations_rules before insert or update on public.labour_observations
  for each row execute function private.labour_observation_rules();

-- ---------------------------------------------------------------------------
-- RLS, grants, audit
-- ---------------------------------------------------------------------------
alter table public.fetal_biometry      enable row level security;
alter table public.postnatal_visits    enable row level security;
alter table public.labour_observations enable row level security;

revoke all on public.fetal_biometry, public.postnatal_visits, public.labour_observations from anon;
grant select, insert, update on public.fetal_biometry, public.postnatal_visits, public.labour_observations to authenticated;

create policy fetal_biometry_select on public.fetal_biometry
  for select to authenticated using (private.can(patient_id, 'clinical.read'));
create policy fetal_biometry_insert on public.fetal_biometry
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy fetal_biometry_update on public.fetal_biometry
  for update to authenticated
  using (private.can(patient_id, 'clinical.write')) with check (private.can(patient_id, 'clinical.write'));

create policy postnatal_visits_select on public.postnatal_visits
  for select to authenticated
  using (private.can(patient_id, 'clinical.read') and exists (select 1 from public.encounters e where e.id = encounter_id));
create policy postnatal_visits_insert on public.postnatal_visits
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy postnatal_visits_update on public.postnatal_visits
  for update to authenticated
  using (private.can(patient_id, 'clinical.write') and exists (select 1 from public.encounters e where e.id = encounter_id))
  with check (private.can(patient_id, 'clinical.write'));

create policy labour_observations_select on public.labour_observations
  for select to authenticated using (private.can(patient_id, 'clinical.read'));
create policy labour_observations_insert on public.labour_observations
  for insert to authenticated
  with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id));
create policy labour_observations_update on public.labour_observations
  for update to authenticated
  using (private.can(patient_id, 'clinical.write')) with check (private.can(patient_id, 'clinical.write'));

create trigger fetal_biometry_audit after insert or update or delete on public.fetal_biometry
  for each row execute function private.audit_row_change();
create trigger postnatal_visits_audit after insert or update or delete on public.postnatal_visits
  for each row execute function private.audit_row_change();
create trigger labour_observations_audit after insert or update or delete on public.labour_observations
  for each row execute function private.audit_row_change();

revoke execute on function public.record_fetal_scan(uuid, jsonb, jsonb), public.record_postnatal_visit(uuid, jsonb, jsonb)
  from public, anon;
grant execute on function public.record_fetal_scan(uuid, jsonb, jsonb), public.record_postnatal_visit(uuid, jsonb, jsonb),
  public.record_antenatal_visit(uuid, jsonb, jsonb)
  to authenticated;
revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;

-- >>> 20261126000009_gynecology.sql
-- =============================================================================
-- 0009  Gynecology module
--   gyn_profiles        gynecological history (1 row per patient)
--   gyn_visits          structured consultation, 1:1 with a gynecology encounter
--   gyn_ultrasounds     pelvic ultrasound incl. fibroids (FIGO) & IOTA features
--   cervical_screenings cytology / HPV results and the confirmed next step
--   colposcopies        colposcopy, biopsy histology and treatment
--   gyn_procedures      operative / office procedures, histology tracking
--   view gyn_worklist   RLS-respecting per-patient summary
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Gynecological history
-- ---------------------------------------------------------------------------
create table public.gyn_profiles (
  patient_id             uuid primary key references public.patients (id),
  clinic_id              uuid not null references public.clinics (id),
  menarche_age           smallint check (menarche_age between 7 and 20),
  cycle_length_days      smallint check (cycle_length_days between 15 and 120),
  period_duration_days   smallint check (period_duration_days between 1 and 15),
  cycle_regularity       text check (cycle_regularity in ('regular', 'irregular', 'absent')),
  menstrual_flow         text check (menstrual_flow in ('light', 'normal', 'heavy')),
  dysmenorrhea           text check (dysmenorrhea in ('none', 'mild', 'moderate', 'severe')),
  menopause_status       text check (menopause_status in ('premenopausal', 'perimenopausal', 'postmenopausal', 'surgical')),
  menopause_age          smallint check (menopause_age between 25 and 65),
  on_hrt                 boolean,
  contraception          text check (contraception in (
                           'none', 'coc', 'pop', 'iud_copper', 'lng_ius', 'implant', 'injectable', 'condom', 'sterilization', 'other')),
  sexually_active        boolean,
  hpv_vaccinated         text check (hpv_vaccinated in ('yes', 'no', 'unknown')),
  hysterectomy           text check (hysterectomy in ('none', 'subtotal', 'total')),
  previous_gyn_surgery   text,
  notes                  text,
  updated_by             uuid references public.profiles (id) default auth.uid(),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint gyn_menopause_age check (menopause_age is null or coalesce(menopause_status, '') in ('postmenopausal', 'surgical'))
);

create trigger gyn_profiles_touch before update on public.gyn_profiles
  for each row execute function private.touch_updated_at();

create or replace function private.gyn_profile_stamp()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not private.is_server_context() then
    new.updated_by := auth.uid();
  end if;
  if tg_op = 'UPDATE' and new.patient_id <> old.patient_id then
    raise exception 'Profile patient is immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger gyn_profiles_stamp before insert or update on public.gyn_profiles
  for each row execute function private.gyn_profile_stamp();

-- ---------------------------------------------------------------------------
-- Gynecology visits
-- ---------------------------------------------------------------------------
create table public.gyn_visits (
  id                              uuid primary key default gen_random_uuid(),
  patient_id                      uuid not null references public.patients (id),
  clinic_id                       uuid not null references public.clinics (id),
  encounter_id                    uuid not null unique references public.encounters (id),
  visit_date                      date not null default current_date,
  complaints                      text[] not null default '{}' check (complaints <@ array[
                                    'aub', 'pmb', 'amenorrhea', 'pelvic_pain', 'dysmenorrhea', 'discharge', 'pelvic_mass',
                                    'prolapse', 'incontinence', 'menopause_symptoms', 'hirsutism_acne', 'contraception',
                                    'screening', 'infertility', 'dyspareunia', 'postcoital_bleeding', 'breast', 'other']),
  palm_coein                      text[] not null default '{}' check (palm_coein <@ array[
                                    'P', 'A', 'L-SM', 'L-O', 'M', 'C', 'O', 'E', 'I', 'N']),
  lmp                             date,
  pain_score                      smallint check (pain_score between 0 and 10),
  bp_systolic                     smallint check (bp_systolic between 50 and 260),
  bp_diastolic                    smallint check (bp_diastolic between 30 and 180),
  weight_kg                       numeric(5, 1) check (weight_kg between 25 and 300),
  height_cm                       numeric(4, 1) check (height_cm between 100 and 230),
  clinical_hyperandrogenism       boolean,
  biochemical_hyperandrogenism    boolean,
  abdominal_exam                  text,
  speculum_exam                   text,
  bimanual_exam                   text,
  uterus_size                     text check (uterus_size in ('normal', 'bulky', 'enlarged_lt12w', 'enlarged_ge12w', 'not_assessed')),
  adnexal_tenderness              boolean,
  cervical_motion_tenderness      boolean,
  pop_stage                       smallint check (pop_stage between 0 and 4),
  diagnosis                       text,
  notes                           text,
  created_by                      uuid references public.profiles (id) default auth.uid(),
  created_at                      timestamptz not null default now(),
  updated_at                      timestamptz not null default now(),
  constraint gyn_bp_pair check (
    (bp_systolic is null) = (bp_diastolic is null) and (bp_systolic is null or bp_systolic > bp_diastolic)
  ),
  constraint gyn_lmp_not_after_visit check (lmp is null or lmp <= visit_date)
);

create index gyn_visits_patient_idx on public.gyn_visits (patient_id, visit_date);

create trigger gyn_visits_touch before update on public.gyn_visits
  for each row execute function private.touch_updated_at();

create or replace function private.gyn_visit_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_patient uuid;
  v_spec    public.specialty;
begin
  if tg_op = 'UPDATE' then
    if new.patient_id <> old.patient_id or new.encounter_id <> old.encounter_id then
      raise exception 'Visit links are immutable' using errcode = '42501';
    end if;
    if not private.is_server_context()
       and private.encounter_status(old.encounter_id) in ('signed', 'amended') then
      raise exception 'This visit is signed; record an amendment instead' using errcode = '42501';
    end if;
    return new;
  end if;
  select patient_id, specialty into v_patient, v_spec from public.encounters where id = new.encounter_id;
  if v_patient is distinct from new.patient_id or v_spec <> 'gynecology' then
    raise exception 'Visit must link to a gynecology encounter of the same patient' using errcode = '23514';
  end if;
  if not private.is_server_context() then
    new.created_by := auth.uid();
  end if;
  return new;
end;
$$;

create trigger gyn_visits_rules before insert or update on public.gyn_visits
  for each row execute function private.gyn_visit_rules();

create or replace function public.record_gyn_visit(
  p_patient_id  uuid,
  p_visit       jsonb,
  p_encounter   jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_clinic uuid;
  v_date   date := coalesce((p_visit ->> 'visit_date')::date, current_date);
  v_enc    uuid;
  v_id     uuid;
  v_row    public.gyn_visits;
begin
  select clinic_id into v_clinic from public.patients where id = p_patient_id and deleted_at is null;
  if v_clinic is null then
    raise exception 'Patient not found' using errcode = 'P0002';
  end if;
  if v_date > current_date then
    raise exception 'Visit date cannot be in the future' using errcode = '22023';
  end if;
  v_clinic := coalesce(nullif(p_encounter ->> 'clinic_id', '')::uuid, v_clinic);

  insert into public.encounters
    (patient_id, clinic_id, specialty, encounter_type, encounter_at, is_private, chief_complaint, assessment, plan)
  values
    (p_patient_id, v_clinic, 'gynecology', coalesce(p_encounter ->> 'encounter_type', 'consultation'),
     case when v_date = current_date then now() else v_date::timestamptz end,
     coalesce((p_encounter ->> 'is_private')::boolean, false),
     p_encounter ->> 'chief_complaint', p_encounter ->> 'assessment', p_encounter ->> 'plan')
  returning id into v_enc;

  v_row := jsonb_populate_record(null::public.gyn_visits, p_visit);
  insert into public.gyn_visits
    (patient_id, clinic_id, encounter_id, visit_date, complaints, palm_coein, lmp, pain_score, bp_systolic, bp_diastolic,
     weight_kg, height_cm, clinical_hyperandrogenism, biochemical_hyperandrogenism, abdominal_exam, speculum_exam,
     bimanual_exam, uterus_size, adnexal_tenderness, cervical_motion_tenderness, pop_stage, diagnosis, notes)
  values
    (p_patient_id, v_clinic, v_enc, v_date, coalesce(v_row.complaints, '{}'), coalesce(v_row.palm_coein, '{}'), v_row.lmp,
     v_row.pain_score, v_row.bp_systolic, v_row.bp_diastolic, v_row.weight_kg, v_row.height_cm,
     v_row.clinical_hyperandrogenism, v_row.biochemical_hyperandrogenism, v_row.abdominal_exam, v_row.speculum_exam,
     v_row.bimanual_exam, v_row.uterus_size, v_row.adnexal_tenderness, v_row.cervical_motion_tenderness, v_row.pop_stage,
     v_row.diagnosis, v_row.notes)
  returning id into v_id;
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Pelvic ultrasound
-- ---------------------------------------------------------------------------
create table public.gyn_ultrasounds (
  id                         uuid primary key default gen_random_uuid(),
  patient_id                 uuid not null references public.patients (id),
  clinic_id                  uuid not null references public.clinics (id),
  performed_at               timestamptz not null default now(),
  route                      text check (route in ('transabdominal', 'transvaginal', 'transrectal')),
  uterus_length_mm           numeric(5, 1) check (uterus_length_mm between 10 and 300),
  uterus_ap_mm               numeric(5, 1) check (uterus_ap_mm between 5 and 200),
  uterus_width_mm            numeric(5, 1) check (uterus_width_mm between 5 and 200),
  uterus_position            text check (uterus_position in ('anteverted', 'retroverted', 'axial', 'absent')),
  endometrial_thickness_mm   numeric(4, 1) check (endometrial_thickness_mm between 0 and 50),
  endometrium_appearance     text check (endometrium_appearance in ('normal', 'thickened', 'heterogeneous', 'polyp', 'fluid', 'not_seen')),
  fibroids                   jsonb not null default '[]'::jsonb check (jsonb_typeof(fibroids) = 'array' and jsonb_array_length(fibroids) <= 30),
  right_ovary_volume_ml      numeric(5, 1) check (right_ovary_volume_ml between 0 and 1000),
  left_ovary_volume_ml       numeric(5, 1) check (left_ovary_volume_ml between 0 and 1000),
  right_follicle_count       smallint check (right_follicle_count between 0 and 100),
  left_follicle_count        smallint check (left_follicle_count between 0 and 100),
  adnexal_mass               boolean not null default false,
  mass_side                  text check (mass_side in ('right', 'left', 'bilateral')),
  mass_max_diameter_mm       numeric(5, 1) check (mass_max_diameter_mm between 1 and 400),
  iota_b_features            text[] not null default '{}' check (iota_b_features <@ array['B1', 'B2', 'B3', 'B4', 'B5']),
  iota_m_features            text[] not null default '{}' check (iota_m_features <@ array['M1', 'M2', 'M3', 'M4', 'M5']),
  free_fluid                 text check (free_fluid in ('none', 'small', 'moderate', 'large')),
  impression                 text,
  performed_by               uuid references public.profiles (id) default auth.uid(),
  created_at                 timestamptz not null default now(),
  constraint gyn_us_mass_fields check (
    adnexal_mass or (mass_side is null and mass_max_diameter_mm is null
                     and cardinality(iota_b_features) = 0 and cardinality(iota_m_features) = 0)
  )
);

create index gyn_ultrasounds_patient_idx on public.gyn_ultrasounds (patient_id, performed_at);

-- ---------------------------------------------------------------------------
-- Cervical screening & colposcopy
-- ---------------------------------------------------------------------------
create table public.cervical_screenings (
  id                    uuid primary key default gen_random_uuid(),
  patient_id            uuid not null references public.patients (id),
  clinic_id             uuid not null references public.clinics (id),
  sample_date           date not null,
  test_type             text not null check (test_type in ('cytology', 'hpv_primary', 'cotest')),
  hpv_result            text check (hpv_result in ('negative', 'hpv16', 'hpv18', 'hpv16_18', 'other_hr', 'positive_untyped')),
  cytology_result       text check (cytology_result in (
                          'nilm', 'asc_us', 'lsil', 'asc_h', 'hsil', 'agc', 'scc', 'adenocarcinoma', 'unsatisfactory')),
  status                text not null default 'pending' check (status in ('pending', 'resulted')),
  recommendation        text,
  next_due_date         date,
  notes                 text,
  recorded_by           uuid references public.profiles (id) default auth.uid(),
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint screening_not_future check (sample_date <= current_date),
  constraint screening_result_matches_test check (
    status = 'pending'
    or (test_type = 'cytology' and cytology_result is not null)
    or (test_type = 'hpv_primary' and hpv_result is not null)
    or (test_type = 'cotest' and cytology_result is not null and hpv_result is not null)
  ),
  constraint screening_next_due_after check (next_due_date is null or next_due_date > sample_date)
);

create index cervical_screenings_patient_idx on public.cervical_screenings (patient_id, sample_date);

create trigger cervical_screenings_touch before update on public.cervical_screenings
  for each row execute function private.touch_updated_at();

create table public.colposcopies (
  id               uuid primary key default gen_random_uuid(),
  patient_id       uuid not null references public.patients (id),
  clinic_id        uuid not null references public.clinics (id),
  screening_id     uuid references public.cervical_screenings (id),
  performed_at     date not null default current_date,
  tz_type          smallint check (tz_type between 1 and 3),
  findings         text check (findings in ('normal', 'minor_grade1', 'major_grade2', 'suspicious_invasion', 'non_specific')),
  biopsy_taken     boolean not null default false,
  histology        text check (histology in ('pending', 'normal', 'cin1', 'cin2', 'cin3', 'ais', 'invasive')),
  treatment        text check (treatment in ('none', 'lletz', 'cone', 'ablation', 'follow_up')),
  notes            text,
  performed_by     uuid references public.profiles (id) default auth.uid(),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint colposcopy_not_future check (performed_at <= current_date),
  constraint colposcopy_histology_needs_biopsy check (histology is null or biopsy_taken or coalesce(treatment, '') in ('lletz', 'cone'))
);

create trigger colposcopies_touch before update on public.colposcopies
  for each row execute function private.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Procedures
-- ---------------------------------------------------------------------------
create table public.gyn_procedures (
  id                uuid primary key default gen_random_uuid(),
  patient_id        uuid not null references public.patients (id),
  clinic_id         uuid not null references public.clinics (id),
  performed_at      date not null default current_date,
  procedure_code    text not null check (procedure_code in (
                      'diagnostic_hysteroscopy', 'operative_hysteroscopy', 'polypectomy', 'endometrial_biopsy', 'd_and_c',
                      'iud_insertion', 'iud_removal', 'diagnostic_laparoscopy', 'ovarian_cystectomy', 'oophorectomy',
                      'salpingectomy', 'myomectomy', 'hysterectomy', 'lletz', 'cone_biopsy', 'colporrhaphy',
                      'sling', 'endometriosis_excision', 'other')),
  approach          text check (approach in ('office', 'hysteroscopic', 'laparoscopic', 'robotic', 'open', 'vaginal')),
  indication        text,
  findings          text,
  surgeon_id        uuid references public.profiles (id) default auth.uid(),
  assistant         text,
  anesthesia        text check (anesthesia in ('none', 'local', 'sedation', 'regional', 'general')),
  blood_loss_ml     integer check (blood_loss_ml between 0 and 20000),
  complications     text,
  clavien_dindo     text check (clavien_dindo in ('none', 'I', 'II', 'IIIa', 'IIIb', 'IVa', 'IVb', 'V')),
  histology_status  text not null default 'not_sent' check (histology_status in ('not_sent', 'pending', 'received')),
  histology_result  text,
  notes             text,
  recorded_by       uuid references public.profiles (id) default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint procedure_not_future check (performed_at <= current_date),
  constraint procedure_histology_result check (histology_status = 'received' or histology_result is null)
);

create index gyn_procedures_patient_idx on public.gyn_procedures (patient_id, performed_at);

create trigger gyn_procedures_touch before update on public.gyn_procedures
  for each row execute function private.touch_updated_at();

-- Stamp authors & keep links immutable for the directly-inserted tables.
create or replace function private.gyn_record_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb;
begin
  if tg_op = 'UPDATE' then
    v_old := to_jsonb(old);
    if v_new ->> 'patient_id' <> v_old ->> 'patient_id' then
      raise exception 'Record patient is immutable' using errcode = '42501';
    end if;
    return new;
  end if;
  if not private.is_server_context() then
    case tg_table_name
      when 'gyn_ultrasounds' then new := jsonb_populate_record(new, jsonb_build_object('performed_by', auth.uid()));
      when 'cervical_screenings' then new := jsonb_populate_record(new, jsonb_build_object('recorded_by', auth.uid()));
      when 'colposcopies' then new := jsonb_populate_record(new, jsonb_build_object('performed_by', auth.uid()));
      when 'gyn_procedures' then new := jsonb_populate_record(new, jsonb_build_object('recorded_by', auth.uid(),
                                  'surgeon_id', coalesce(v_new ->> 'surgeon_id', auth.uid()::text)));
      else null;
    end case;
  end if;
  return new;
end;
$$;

create trigger gyn_ultrasounds_rules before insert or update on public.gyn_ultrasounds
  for each row execute function private.gyn_record_rules();
create trigger cervical_screenings_rules before insert or update on public.cervical_screenings
  for each row execute function private.gyn_record_rules();
create trigger colposcopies_rules before insert or update on public.colposcopies
  for each row execute function private.gyn_record_rules();
create trigger gyn_procedures_rules before insert or update on public.gyn_procedures
  for each row execute function private.gyn_record_rules();

-- A colposcopy linked to a screening must be the same patient's.
create or replace function private.colposcopy_link_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.screening_id is not null and not exists (
    select 1 from public.cervical_screenings s where s.id = new.screening_id and s.patient_id = new.patient_id
  ) then
    raise exception 'Colposcopy must link to a screening of the same patient' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger colposcopies_link before insert or update on public.colposcopies
  for each row execute function private.colposcopy_link_rules();

-- Registering gynecology data tags the patient with the specialty.
create or replace function private.gyn_tag_patient()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.patients
     set specialties = array_append(specialties, 'gynecology'::public.specialty)
   where id = new.patient_id and not ('gynecology' = any (specialties));
  return new;
end;
$$;

create trigger gyn_profiles_tag after insert on public.gyn_profiles
  for each row execute function private.gyn_tag_patient();
create trigger gyn_visits_tag after insert on public.gyn_visits
  for each row execute function private.gyn_tag_patient();

-- ---------------------------------------------------------------------------
-- RLS, grants, audit
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array['gyn_profiles', 'gyn_visits', 'gyn_ultrasounds', 'cervical_screenings', 'colposcopies', 'gyn_procedures'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update on public.%I to authenticated', t);
    execute format('create trigger %I after insert or update or delete on public.%I
                      for each row execute function private.audit_row_change()', t || '_audit', t);
    if t = 'gyn_visits' then
      -- visit inherits its encounter's visibility (private notes)
      execute format($p$create policy %I on public.%I for select to authenticated
        using (private.can(patient_id, 'clinical.read') and exists (select 1 from public.encounters e where e.id = encounter_id))$p$, t || '_select', t);
      execute format($p$create policy %I on public.%I for update to authenticated
        using (private.can(patient_id, 'clinical.write') and exists (select 1 from public.encounters e where e.id = encounter_id))
        with check (private.can(patient_id, 'clinical.write'))$p$, t || '_update', t);
    else
      execute format($p$create policy %I on public.%I for select to authenticated
        using (private.can(patient_id, 'clinical.read'))$p$, t || '_select', t);
      execute format($p$create policy %I on public.%I for update to authenticated
        using (private.can(patient_id, 'clinical.write')) with check (private.can(patient_id, 'clinical.write'))$p$, t || '_update', t);
    end if;
    execute format($p$create policy %I on public.%I for insert to authenticated
      with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id))$p$, t || '_insert', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- Gynecology worklist (SECURITY INVOKER view)
-- ---------------------------------------------------------------------------
create view public.gyn_worklist
with (security_invoker = true)
as
select
  p.id as patient_id, p.clinic_id, p.mrn, p.first_name_en, p.last_name_en, p.first_name_ar, p.last_name_ar, p.date_of_birth,
  gp.menopause_status, gp.hysterectomy,
  s.sample_date      as last_screening_date,
  s.test_type        as last_screening_test,
  s.hpv_result       as last_hpv_result,
  s.cytology_result  as last_cytology_result,
  s.status           as last_screening_status,
  s.next_due_date    as screening_next_due,
  s.recommendation   as screening_recommendation,
  (select max(c.performed_at) from public.colposcopies c where c.patient_id = p.id) as last_colposcopy_date,
  (select count(*) from public.gyn_procedures x where x.patient_id = p.id and x.histology_status = 'pending')
    + (select count(*) from public.colposcopies c where c.patient_id = p.id and c.histology = 'pending') as pending_histology,
  (select max(v.visit_date) from public.gyn_visits v where v.patient_id = p.id) as last_visit_date,
  (select v.complaints from public.gyn_visits v where v.patient_id = p.id order by v.visit_date desc, v.created_at desc limit 1) as last_complaints
from public.patients p
left join public.gyn_profiles gp on gp.patient_id = p.id
left join lateral (
  select * from public.cervical_screenings cs where cs.patient_id = p.id order by cs.sample_date desc, cs.created_at desc limit 1
) s on true
where p.deleted_at is null and 'gynecology' = any (p.specialties);

revoke all on public.gyn_worklist from anon;
grant select on public.gyn_worklist to authenticated;

revoke execute on function public.record_gyn_visit(uuid, jsonb, jsonb) from public, anon;
grant execute on function public.record_gyn_visit(uuid, jsonb, jsonb) to authenticated;
revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;

-- >>> 20261126000010_gynecology_extended.sql
-- =============================================================================
-- 0010  Gynecology, extended: lab results (shared), menopause (MRS),
--       urogynecology (ICIQ-UI SF), ovarian-mass risk fields (O-RADS, RMI)
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Lab results — generic, reusable by every specialty. Each value is stored
-- with the reporting laboratory's reference range (ranges differ per lab).
-- ---------------------------------------------------------------------------
create table public.lab_results (
  id            uuid primary key default gen_random_uuid(),
  patient_id    uuid not null references public.patients (id),
  clinic_id     uuid not null references public.clinics (id),
  collected_at  date not null,
  test_code     text not null check (test_code in (
                  'fsh', 'lh', 'estradiol', 'progesterone', 'amh', 'prolactin', 'tsh', 'free_t4', 'testosterone', 'shbg',
                  'dheas', 'oh17_progesterone', 'hba1c', 'fasting_glucose', 'ca125', 'he4', 'hemoglobin', 'ferritin',
                  'beta_hcg', 'vitamin_d')),
  value         numeric(12, 3) not null check (value >= 0),
  unit          text not null check (length(unit) between 1 and 20),
  ref_low       numeric(12, 3),
  ref_high      numeric(12, 3),
  cycle_day     smallint check (cycle_day between 1 and 60),
  notes         text,
  recorded_by   uuid references public.profiles (id) default auth.uid(),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint lab_ref_order check (ref_low is null or ref_high is null or ref_low <= ref_high),
  constraint lab_not_future check (collected_at <= current_date)
);

create index lab_results_patient_idx on public.lab_results (patient_id, collected_at, test_code);

create trigger lab_results_touch before update on public.lab_results
  for each row execute function private.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Menopause Rating Scale (Heinemann et al.) — 11 items scored 0–4.
-- Subscales: somatic 1,2,3,11 · psychological 4,5,6,7 · urogenital 8,9,10.
-- ---------------------------------------------------------------------------
create table public.menopause_assessments (
  id             uuid primary key default gen_random_uuid(),
  patient_id     uuid not null references public.patients (id),
  clinic_id      uuid not null references public.clinics (id),
  assessed_at    date not null default current_date,
  items          smallint[] not null check (cardinality(items) = 11 and 0 <= all (items) and 4 >= all (items)),
  total          smallint,
  somatic        smallint,
  psychological  smallint,
  urogenital     smallint,
  notes          text,
  recorded_by    uuid references public.profiles (id) default auth.uid(),
  created_at     timestamptz not null default now(),
  constraint mrs_not_future check (assessed_at <= current_date)
);

create or replace function private.mrs_score()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.somatic := new.items[1] + new.items[2] + new.items[3] + new.items[11];
  new.psychological := new.items[4] + new.items[5] + new.items[6] + new.items[7];
  new.urogenital := new.items[8] + new.items[9] + new.items[10];
  new.total := new.somatic + new.psychological + new.urogenital;
  return new;
end;
$$;

create trigger menopause_assessments_score before insert or update on public.menopause_assessments
  for each row execute function private.mrs_score();

-- ---------------------------------------------------------------------------
-- ICIQ-UI Short Form — frequency 0–5, amount 0/2/4/6, interference 0–10;
-- score 0–21; Q6 leak situations are self-diagnostic (unscored).
-- ---------------------------------------------------------------------------
create table public.urogyn_assessments (
  id               uuid primary key default gen_random_uuid(),
  patient_id       uuid not null references public.patients (id),
  clinic_id        uuid not null references public.clinics (id),
  assessed_at      date not null default current_date,
  frequency        smallint not null check (frequency between 0 and 5),
  amount           smallint not null check (amount in (0, 2, 4, 6)),
  interference     smallint not null check (interference between 0 and 10),
  score            smallint,
  leak_situations  text[] not null default '{}' check (leak_situations <@ array[
                     'never', 'before_toilet', 'cough_sneeze', 'asleep', 'physical_activity', 'after_voiding',
                     'no_reason', 'all_the_time']),
  notes            text,
  recorded_by      uuid references public.profiles (id) default auth.uid(),
  created_at       timestamptz not null default now(),
  constraint iciq_not_future check (assessed_at <= current_date)
);

create or replace function private.iciq_score()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.score := new.frequency + new.amount + new.interference;
  return new;
end;
$$;

create trigger urogyn_assessments_score before insert or update on public.urogyn_assessments
  for each row execute function private.iciq_score();

-- ---------------------------------------------------------------------------
-- Ovarian-mass risk fields on pelvic ultrasound
--   orads_category  clinician-assigned ACR O-RADS US category (0–5)
--   rmi_features    RMI ultrasound features (Jacobs 1990)
-- ---------------------------------------------------------------------------
alter table public.gyn_ultrasounds
  add column orads_category smallint check (orads_category between 0 and 5),
  add column rmi_features text[] not null default '{}' check (rmi_features <@ array[
    'multilocular', 'solid_areas', 'bilateral', 'ascites', 'metastases']);

alter table public.gyn_ultrasounds drop constraint gyn_us_mass_fields;
alter table public.gyn_ultrasounds add constraint gyn_us_mass_fields check (
  adnexal_mass or (mass_side is null and mass_max_diameter_mm is null and orads_category is null
                   and cardinality(iota_b_features) = 0 and cardinality(iota_m_features) = 0 and cardinality(rmi_features) = 0)
);

-- ---------------------------------------------------------------------------
-- Author stamping, immutable patient link, RLS, audit
-- ---------------------------------------------------------------------------
create or replace function private.gyn_ext_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' then
    if new.patient_id <> old.patient_id then
      raise exception 'Record patient is immutable' using errcode = '42501';
    end if;
    return new;
  end if;
  if not private.is_server_context() then
    new := jsonb_populate_record(new, jsonb_build_object('recorded_by', auth.uid()));
  end if;
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['lab_results', 'menopause_assessments', 'urogyn_assessments'] loop
    execute format('create trigger %I before insert or update on public.%I for each row execute function private.gyn_ext_rules()', t || '_rules', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update on public.%I to authenticated', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function private.audit_row_change()', t || '_audit', t);
    execute format($p$create policy %I on public.%I for select to authenticated using (private.can(patient_id, 'clinical.read'))$p$, t || '_select', t);
    execute format($p$create policy %I on public.%I for insert to authenticated
      with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id))$p$, t || '_insert', t);
    execute format($p$create policy %I on public.%I for update to authenticated
      using (private.can(patient_id, 'clinical.write')) with check (private.can(patient_id, 'clinical.write'))$p$, t || '_update', t);
  end loop;
end;
$$;

revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;

-- >>> 20261126000011_fertility.sql
-- =============================================================================
-- 0011  Infertility & reproductive medicine
--   fertility_profiles     couple work-up (1 per patient)
--   semen_analyses         partner semen analyses (computed total count / TMSC)
--   fertility_cycles       extended: protocol, trigger, retrieval, freeze-all
--   stimulation_monitoring follicle tracking, hormones, endometrium
--   embryos                embryology & cryostorage (Gardner / cleavage grading)
--   embryo_transfers       transfer, β-hCG and pregnancy outcome
--   views                  fertility_worklist, cryo_inventory (SECURITY INVOKER)
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Couple work-up
-- ---------------------------------------------------------------------------
create table public.fertility_profiles (
  patient_id           uuid primary key references public.patients (id),
  clinic_id            uuid not null references public.clinics (id),
  infertility_type     text check (infertility_type in ('primary', 'secondary')),
  duration_months      smallint check (duration_months between 0 and 600),
  female_factors       text[] not null default '{}' check (female_factors <@ array[
                         'ovulatory', 'tubal', 'endometriosis', 'uterine', 'diminished_reserve', 'unexplained', 'other']),
  male_factor          boolean,
  tubal_assessment     text check (tubal_assessment in ('not_done', 'bilateral_patent', 'unilateral_patent', 'bilateral_blocked', 'hydrosalpinx')),
  tubal_method         text check (tubal_method in ('hsg', 'hycosy', 'laparoscopy')),
  partner_name         text,
  partner_dob          date check (partner_dob is null or partner_dob < current_date),
  partner_phone        text,
  partner_blood_group  text check (partner_blood_group in ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-')),
  previous_treatments  text,
  notes                text,
  updated_by           uuid references public.profiles (id) default auth.uid(),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  constraint tubal_method_needs_result check (tubal_method is null or coalesce(tubal_assessment, 'not_done') <> 'not_done')
);

create trigger fertility_profiles_touch before update on public.fertility_profiles
  for each row execute function private.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Semen analysis (stored on the female partner's record = the couple's chart)
-- ---------------------------------------------------------------------------
create table public.semen_analyses (
  id                      uuid primary key default gen_random_uuid(),
  patient_id              uuid not null references public.patients (id),
  clinic_id               uuid not null references public.clinics (id),
  collected_at            date not null,
  sample_type             text not null default 'diagnostic' check (sample_type in ('diagnostic', 'post_wash', 'frozen_thawed', 'surgical')),
  abstinence_days         smallint check (abstinence_days between 0 and 30),
  volume_ml               numeric(4, 1) check (volume_ml between 0 and 20),
  concentration_m_ml      numeric(6, 2) check (concentration_m_ml between 0 and 500),
  progressive_pct         numeric(4, 1) check (progressive_pct between 0 and 100),
  total_motility_pct      numeric(4, 1) check (total_motility_pct between 0 and 100),
  normal_forms_pct        numeric(4, 1) check (normal_forms_pct between 0 and 100),
  vitality_pct            numeric(4, 1) check (vitality_pct between 0 and 100),
  ph                      numeric(3, 1) check (ph between 6 and 9),
  leukocytes_m_ml         numeric(4, 2) check (leukocytes_m_ml between 0 and 50),
  dna_fragmentation_pct   numeric(4, 1) check (dna_fragmentation_pct between 0 and 100),
  total_count_m           numeric(8, 2) generated always as (volume_ml * concentration_m_ml) stored,
  tmsc_m                  numeric(8, 2) generated always as (volume_ml * concentration_m_ml * progressive_pct / 100) stored,
  notes                   text,
  recorded_by             uuid references public.profiles (id) default auth.uid(),
  created_at              timestamptz not null default now(),
  constraint semen_motility_order check (progressive_pct is null or total_motility_pct is null or progressive_pct <= total_motility_pct),
  constraint semen_not_future check (collected_at <= current_date)
);

create index semen_analyses_patient_idx on public.semen_analyses (patient_id, collected_at);

-- ---------------------------------------------------------------------------
-- Treatment cycles (extends the Phase 1 table)
-- ---------------------------------------------------------------------------
alter table public.fertility_cycles
  add column cycle_number          smallint check (cycle_number between 1 and 50),
  add column day1_date             date,
  add column indication            text,
  add column stim_protocol         text check (stim_protocol in (
                                     'antagonist', 'long_agonist', 'short_agonist', 'ppos', 'mild', 'natural', 'letrozole', 'clomiphene', 'hrt_fet', 'natural_fet')),
  add column starting_dose_iu      smallint check (starting_dose_iu between 0 and 600),
  add column gonadotropin          text,
  add column trigger_type          text check (trigger_type in ('hcg', 'gnrh_agonist', 'dual', 'none')),
  add column trigger_at            timestamptz,
  add column insemination          text check (insemination in ('ivf', 'icsi', 'iui', 'none')),
  add column sperm_source          text check (sperm_source in ('partner_fresh', 'partner_frozen', 'donor', 'surgical')),
  add column retrieval_at          date,
  add column oocytes_retrieved     smallint check (oocytes_retrieved between 0 and 100),
  add column mii_oocytes           smallint check (mii_oocytes between 0 and 100),
  add column fertilized_2pn        smallint check (fertilized_2pn between 0 and 100),
  add column retrieval_complications text,
  add column freeze_all            boolean not null default false,
  add column freeze_all_reason     text check (freeze_all_reason in ('ohss_risk', 'progesterone', 'endometrium', 'pgt', 'elective', 'other')),
  add column cancel_reason         text,
  add column updated_by            uuid references public.profiles (id),
  add constraint cycle_mii_le_oocytes check (mii_oocytes is null or oocytes_retrieved is null or mii_oocytes <= oocytes_retrieved),
  add constraint cycle_2pn_le_oocytes check (fertilized_2pn is null or oocytes_retrieved is null or fertilized_2pn <= oocytes_retrieved),
  add constraint cycle_freeze_reason check (freeze_all or freeze_all_reason is null),
  add constraint cycle_cancel_reason check (status = 'cancelled' or cancel_reason is null),
  add constraint cycle_retrieval_after_start check (retrieval_at is null or retrieval_at >= start_date);

create or replace function private.fertility_cycle_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.patient_id <> old.patient_id then
    raise exception 'Cycle patient is immutable' using errcode = '42501';
  end if;
  if not private.is_server_context() then
    new.updated_by := auth.uid();
    if tg_op = 'INSERT' then
      new.created_by := auth.uid();
    end if;
  end if;
  if tg_op = 'INSERT' and new.cycle_number is null then
    select coalesce(max(cycle_number), 0) + 1 into new.cycle_number
    from public.fertility_cycles where patient_id = new.patient_id;
  end if;
  return new;
end;
$$;

create trigger fertility_cycles_rules before insert or update on public.fertility_cycles
  for each row execute function private.fertility_cycle_rules();

-- ---------------------------------------------------------------------------
-- Stimulation monitoring
-- ---------------------------------------------------------------------------
create table public.stimulation_monitoring (
  id                uuid primary key default gen_random_uuid(),
  cycle_id          uuid not null references public.fertility_cycles (id) on delete cascade,
  patient_id        uuid not null references public.patients (id),
  clinic_id         uuid not null references public.clinics (id),
  monitored_on      date not null default current_date,
  stim_day          smallint check (stim_day between 0 and 30),
  e2_pmol_l         numeric(8, 1) check (e2_pmol_l between 0 and 50000),
  lh_iu_l           numeric(5, 1) check (lh_iu_l between 0 and 200),
  p4_nmol_l         numeric(5, 2) check (p4_nmol_l between 0 and 200),
  endometrium_mm    numeric(4, 1) check (endometrium_mm between 0 and 30),
  follicles_right   numeric[] not null default '{}' check (cardinality(follicles_right) <= 60 and (cardinality(follicles_right) = 0 or (2 <= all (follicles_right) and 40 >= all (follicles_right)))),
  follicles_left    numeric[] not null default '{}' check (cardinality(follicles_left) <= 60 and (cardinality(follicles_left) = 0 or (2 <= all (follicles_left) and 40 >= all (follicles_left)))),
  fsh_dose_iu       smallint check (fsh_dose_iu between 0 and 600),
  antagonist        boolean not null default false,
  notes             text,
  recorded_by       uuid references public.profiles (id) default auth.uid(),
  created_at        timestamptz not null default now(),
  constraint monitoring_not_future check (monitored_on <= current_date)
);

create index stimulation_monitoring_cycle_idx on public.stimulation_monitoring (cycle_id, monitored_on);

-- ---------------------------------------------------------------------------
-- Embryology & cryostorage
-- ---------------------------------------------------------------------------
create table public.embryos (
  id                    uuid primary key default gen_random_uuid(),
  cycle_id              uuid not null references public.fertility_cycles (id),
  patient_id            uuid not null references public.patients (id),
  clinic_id             uuid not null references public.clinics (id),
  embryo_no             smallint not null check (embryo_no between 1 and 100),
  day_observed          smallint check (day_observed between 1 and 7),
  stage                 text not null default 'cleavage' check (stage in ('zygote', 'cleavage', 'morula', 'blastocyst', 'arrested')),
  cell_count            smallint check (cell_count between 1 and 32),
  fragmentation_grade   smallint check (fragmentation_grade between 1 and 4),
  blast_expansion       smallint check (blast_expansion between 1 and 6),
  icm_grade             text check (icm_grade in ('A', 'B', 'C')),
  te_grade              text check (te_grade in ('A', 'B', 'C')),
  pgt_result            text not null default 'not_tested' check (pgt_result in ('not_tested', 'pending', 'euploid', 'aneuploid', 'mosaic', 'no_result')),
  status                text not null default 'in_culture' check (status in ('in_culture', 'transferred', 'frozen', 'thawed', 'discarded')),
  frozen_at             date,
  storage_location      text,
  consent_expires_on    date,
  notes                 text,
  updated_by            uuid references public.profiles (id) default auth.uid(),
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  unique (cycle_id, embryo_no),
  constraint embryo_blast_grades check (stage = 'blastocyst' or (blast_expansion is null and icm_grade is null and te_grade is null)),
  constraint embryo_frozen_storage check (status <> 'frozen' or (frozen_at is not null and storage_location is not null)),
  constraint embryo_consent_after_freeze check (consent_expires_on is null or frozen_at is null or consent_expires_on > frozen_at)
);

create index embryos_cycle_idx on public.embryos (cycle_id);
create index embryos_frozen_idx on public.embryos (clinic_id) where status = 'frozen';

create trigger embryos_touch before update on public.embryos
  for each row execute function private.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Embryo transfer & outcome
-- ---------------------------------------------------------------------------
create table public.embryo_transfers (
  id                   uuid primary key default gen_random_uuid(),
  cycle_id             uuid not null references public.fertility_cycles (id),
  patient_id           uuid not null references public.patients (id),
  clinic_id            uuid not null references public.clinics (id),
  transfer_on          date not null,
  fresh                boolean not null,
  embryo_ids           uuid[] not null default '{}',
  embryos_transferred  smallint not null check (embryos_transferred between 1 and 4),
  embryo_day           smallint not null check (embryo_day in (2, 3, 5, 6, 7)),
  endometrium_mm       numeric(4, 1) check (endometrium_mm between 0 and 30),
  difficulty           text check (difficulty in ('easy', 'difficult', 'very_difficult')),
  beta_hcg_on          date,
  beta_hcg_value       numeric(8, 1) check (beta_hcg_value >= 0),
  gestational_sacs     smallint check (gestational_sacs between 0 and 6),
  fetal_hearts         smallint check (fetal_hearts between 0 and 6),
  outcome              text not null default 'pending' check (outcome in (
                         'pending', 'negative', 'biochemical', 'clinical', 'ectopic', 'miscarriage', 'ongoing')),
  pregnancy_id         uuid references public.pregnancies (id),
  notes                text,
  recorded_by          uuid references public.profiles (id) default auth.uid(),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  constraint transfer_not_future check (transfer_on <= current_date),
  constraint transfer_hearts_le_sacs check (fetal_hearts is null or gestational_sacs is null or fetal_hearts <= gestational_sacs),
  constraint transfer_hcg_after check (beta_hcg_on is null or beta_hcg_on > transfer_on),
  constraint transfer_embryo_count check (cardinality(embryo_ids) = 0 or cardinality(embryo_ids) = embryos_transferred),
  constraint transfer_clinical_needs_sac check (outcome not in ('clinical', 'ongoing') or coalesce(gestational_sacs, 0) >= 1)
);

create index embryo_transfers_cycle_idx on public.embryo_transfers (cycle_id);

create trigger embryo_transfers_touch before update on public.embryo_transfers
  for each row execute function private.touch_updated_at();

-- Embryo / transfer integrity: same patient as the cycle; transferred embryos
-- must belong to the patient and be available; mark them transferred.
create or replace function private.embryo_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (select 1 from public.fertility_cycles c where c.id = new.cycle_id and c.patient_id = new.patient_id) then
    raise exception 'Record must belong to a cycle of the same patient' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and (new.cycle_id <> old.cycle_id or new.patient_id <> old.patient_id) then
    raise exception 'Links are immutable' using errcode = '42501';
  end if;
  if tg_table_name = 'embryos' and not private.is_server_context() then
    new := jsonb_populate_record(new, jsonb_build_object('updated_by', auth.uid()));
  end if;
  return new;
end;
$$;

create trigger embryos_rules before insert or update on public.embryos
  for each row execute function private.embryo_rules();

create or replace function private.transfer_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_bad int;
begin
  if not exists (select 1 from public.fertility_cycles c where c.id = new.cycle_id and c.patient_id = new.patient_id) then
    raise exception 'Transfer must belong to a cycle of the same patient' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' then
    if new.cycle_id <> old.cycle_id or new.patient_id <> old.patient_id or new.embryo_ids <> old.embryo_ids then
      raise exception 'Transfer links and embryos are immutable' using errcode = '42501';
    end if;
    return new;
  end if;
  select count(*) into v_bad
  from unnest(new.embryo_ids) as eid
  left join public.embryos e on e.id = eid
  where e.id is null or e.patient_id <> new.patient_id or e.status not in ('in_culture', 'frozen', 'thawed');
  if v_bad > 0 then
    raise exception 'Transferred embryos must be this patient''s available embryos' using errcode = '23514';
  end if;
  if not private.is_server_context() then
    new.recorded_by := auth.uid();
  end if;
  return new;
end;
$$;

create trigger embryo_transfers_rules before insert or update on public.embryo_transfers
  for each row execute function private.transfer_rules();

create or replace function private.transfer_mark_embryos()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.embryos set status = 'transferred' where id = any (new.embryo_ids);
  return new;
end;
$$;

create trigger embryo_transfers_mark after insert on public.embryo_transfers
  for each row execute function private.transfer_mark_embryos();

create or replace function private.monitoring_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (select 1 from public.fertility_cycles c where c.id = new.cycle_id and c.patient_id = new.patient_id) then
    raise exception 'Monitoring must belong to a cycle of the same patient' using errcode = '23514';
  end if;
  if not private.is_server_context() and tg_op = 'INSERT' then
    new.recorded_by := auth.uid();
  end if;
  return new;
end;
$$;

create trigger stimulation_monitoring_rules before insert or update on public.stimulation_monitoring
  for each row execute function private.monitoring_rules();

create or replace function private.fertility_simple_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.patient_id <> old.patient_id then
    raise exception 'Record patient is immutable' using errcode = '42501';
  end if;
  if not private.is_server_context() then
    if tg_table_name = 'fertility_profiles' then
      new := jsonb_populate_record(new, jsonb_build_object('updated_by', auth.uid()));
    elsif tg_op = 'INSERT' then
      new := jsonb_populate_record(new, jsonb_build_object('recorded_by', auth.uid()));
    end if;
  end if;
  return new;
end;
$$;

create trigger fertility_profiles_rules before insert or update on public.fertility_profiles
  for each row execute function private.fertility_simple_rules();
create trigger semen_analyses_rules before insert or update on public.semen_analyses
  for each row execute function private.fertility_simple_rules();

-- Tag patient with the infertility specialty when work-up or a cycle is recorded.
create or replace function private.fertility_tag_patient()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.patients
     set specialties = array_append(specialties, 'infertility'::public.specialty)
   where id = new.patient_id and not ('infertility' = any (specialties));
  return new;
end;
$$;

create trigger fertility_profiles_tag after insert on public.fertility_profiles
  for each row execute function private.fertility_tag_patient();
create trigger fertility_cycles_tag after insert on public.fertility_cycles
  for each row execute function private.fertility_tag_patient();

-- ---------------------------------------------------------------------------
-- RLS, grants, audit (fertility_cycles already has RLS + audit from 0002/0004/0005)
-- ---------------------------------------------------------------------------
do $$
declare
  t text;
begin
  foreach t in array array['fertility_profiles', 'semen_analyses', 'stimulation_monitoring', 'embryos', 'embryo_transfers'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update on public.%I to authenticated', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function private.audit_row_change()', t || '_audit', t);
    execute format($p$create policy %I on public.%I for select to authenticated using (private.can(patient_id, 'clinical.read'))$p$, t || '_select', t);
    execute format($p$create policy %I on public.%I for insert to authenticated
      with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id))$p$, t || '_insert', t);
    execute format($p$create policy %I on public.%I for update to authenticated
      using (private.can(patient_id, 'clinical.write')) with check (private.can(patient_id, 'clinical.write'))$p$, t || '_update', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- Views
-- ---------------------------------------------------------------------------
create view public.fertility_worklist
with (security_invoker = true)
as
select
  c.id as cycle_id, c.patient_id, c.clinic_id, c.cycle_type, c.cycle_number, c.status, c.start_date, c.stim_protocol,
  c.trigger_at, c.retrieval_at, c.oocytes_retrieved, c.freeze_all,
  p.mrn, p.first_name_en, p.last_name_en, p.first_name_ar, p.last_name_ar, p.date_of_birth,
  m.monitored_on as last_monitoring_on, m.stim_day as last_stim_day, m.e2_pmol_l as last_e2,
  m.follicles_right as last_follicles_right, m.follicles_left as last_follicles_left,
  t.transfer_on as last_transfer_on, t.embryo_day as last_transfer_day, t.outcome as last_transfer_outcome,
  t.beta_hcg_value as last_beta_hcg
from public.fertility_cycles c
join public.patients p on p.id = c.patient_id and p.deleted_at is null
left join lateral (
  select * from public.stimulation_monitoring sm where sm.cycle_id = c.id order by sm.monitored_on desc, sm.created_at desc limit 1
) m on true
left join lateral (
  select * from public.embryo_transfers et where et.cycle_id = c.id order by et.transfer_on desc limit 1
) t on true
where c.status not in ('completed', 'cancelled') or t.outcome = 'pending';

create view public.cryo_inventory
with (security_invoker = true)
as
select
  e.id as embryo_id, e.patient_id, e.clinic_id, e.cycle_id, e.embryo_no, e.day_observed, e.stage, e.blast_expansion, e.icm_grade,
  e.te_grade, e.cell_count, e.fragmentation_grade, e.pgt_result, e.frozen_at, e.storage_location, e.consent_expires_on,
  c.cycle_number, p.mrn, p.first_name_en, p.last_name_en, p.first_name_ar, p.last_name_ar
from public.embryos e
join public.fertility_cycles c on c.id = e.cycle_id
join public.patients p on p.id = e.patient_id and p.deleted_at is null
where e.status = 'frozen';

revoke all on public.fertility_worklist, public.cryo_inventory from anon;
grant select on public.fertility_worklist, public.cryo_inventory to authenticated;

revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;

-- >>> 20261126000012_fetal_medicine.sql
-- =============================================================================
-- 0012  Fetal medicine
--   Scans reuse the shared scan header public.fetal_assessments (also used by
--   obstetric growth scans) with typed per-fetus child records:
--     fm_first_trimester   11–14 week scan + combined screening (nt_scan)
--     fm_anomaly_scans     ISUOG mid-trimester structural survey (anomaly_scan)
--     fm_dopplers          Doppler & fetal surveillance (doppler)
--   Plus per-pregnancy records:
--     fm_cfdna             cell-free DNA screening
--     fm_procedures        invasive diagnosis and fetal therapy, with results
--   RPC  record_fm_scan    header + per-fetus records atomically
--   View fm_worklist       (SECURITY INVOKER)
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 11–14 weeks: CRL, NT, additional markers, biochemistry, software risks.
-- Risks are stored as entered from the clinic's validated software (e.g. FMF
-- algorithm); the application does not recompute them.
-- ---------------------------------------------------------------------------
create table public.fm_first_trimester (
  id                      uuid primary key default gen_random_uuid(),
  fetal_assessment_id     uuid not null references public.fetal_assessments (id) on delete cascade,
  pregnancy_id            uuid not null references public.pregnancies (id),
  patient_id              uuid not null references public.patients (id),
  clinic_id               uuid not null references public.clinics (id),
  fetus_label             text not null default 'A' check (fetus_label in ('A', 'B', 'C', 'D', 'E', 'F', 'G', 'H')),
  ga_days                 smallint,
  crl_mm                  numeric(4, 1) check (crl_mm between 20 and 100),
  nt_mm                   numeric(3, 1) check (nt_mm between 0.3 and 20),
  nasal_bone              text check (nasal_bone in ('present', 'absent', 'hypoplastic', 'not_assessed')),
  dv_a_wave               text check (dv_a_wave in ('positive', 'absent', 'reversed', 'not_assessed')),
  tricuspid_regurgitation boolean,
  fhr                     smallint check (fhr between 60 and 240),
  papp_a_mom              numeric(5, 3) check (papp_a_mom between 0.01 and 20),
  free_bhcg_mom           numeric(5, 3) check (free_bhcg_mom between 0.01 and 30),
  risk_t21                integer check (risk_t21 between 2 and 1000000),
  risk_t18                integer check (risk_t18 between 2 and 1000000),
  risk_t13                integer check (risk_t13 between 2 and 1000000),
  risk_method             text check (risk_method in ('combined', 'nt_maternal_age', 'combined_extended', 'second_trimester', 'other')),
  risk_software           text,
  early_anatomy           text,
  notes                   text,
  recorded_by             uuid references public.profiles (id) default auth.uid(),
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  unique (fetal_assessment_id, fetus_label),
  constraint ft_risk_method check ((risk_t21 is null and risk_t18 is null and risk_t13 is null) or risk_method is not null)
);

-- ---------------------------------------------------------------------------
-- Mid-trimester anomaly scan. Structures not listed as abnormal or not
-- visualised were seen and normal.
-- ---------------------------------------------------------------------------
create table public.fm_anomaly_scans (
  id                   uuid primary key default gen_random_uuid(),
  fetal_assessment_id  uuid not null references public.fetal_assessments (id) on delete cascade,
  pregnancy_id         uuid not null references public.pregnancies (id),
  patient_id           uuid not null references public.patients (id),
  clinic_id            uuid not null references public.clinics (id),
  fetus_label          text not null default 'A' check (fetus_label in ('A', 'B', 'C', 'D', 'E', 'F', 'G', 'H')),
  ga_days              smallint,
  abnormal_structures  text[] not null default '{}',
  not_visualised       text[] not null default '{}',
  atrium_mm            numeric(4, 1) check (atrium_mm between 0 and 50),
  tcd_mm               numeric(4, 1) check (tcd_mm between 5 and 70),
  cisterna_magna_mm    numeric(4, 1) check (cisterna_magna_mm between 0 and 40),
  nuchal_fold_mm       numeric(4, 1) check (nuchal_fold_mm between 0 and 20),
  renal_pelvis_mm      numeric(4, 1) check (renal_pelvis_mm between 0 and 60),
  cervical_length_mm   numeric(4, 1) check (cervical_length_mm between 0 and 80),
  placenta_location    text check (placenta_location in ('anterior', 'posterior', 'fundal', 'lateral', 'low_lying', 'previa')),
  placenta_os_mm       numeric(4, 1) check (placenta_os_mm between -60 and 150),
  cord_vessels         smallint check (cord_vessels in (2, 3)),
  amniotic_fluid       text check (amniotic_fluid in ('normal', 'oligohydramnios', 'polyhydramnios', 'anhydramnios')),
  soft_markers         text[] not null default '{}' check (soft_markers <@ array[
                         'echogenic_intracardiac_focus', 'choroid_plexus_cyst', 'echogenic_bowel', 'mild_pyelectasis',
                         'short_femur', 'short_humerus', 'nasal_bone_hypoplasia', 'thick_nuchal_fold',
                         'mild_ventriculomegaly', 'single_umbilical_artery', 'aberrant_right_subclavian']),
  fetal_sex            text check (fetal_sex in ('female', 'male', 'undetermined', 'not_disclosed')),
  anomalies            text,
  conclusion           text not null default 'normal' check (conclusion in ('normal', 'soft_markers', 'anomaly_suspected', 'incomplete')),
  notes                text,
  recorded_by          uuid references public.profiles (id) default auth.uid(),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (fetal_assessment_id, fetus_label),
  constraint anomaly_structures_valid check (
    abnormal_structures <@ array[
      'skull', 'midline_falx', 'cavum_septi_pellucidi', 'lateral_ventricles', 'cerebellum', 'cisterna_magna',
      'orbits', 'lips', 'profile', 'neck', 'lungs', 'diaphragm', 'heart_situs', 'four_chamber', 'lvot', 'rvot',
      'three_vessel_trachea', 'stomach', 'bowel', 'abdominal_wall', 'cord_insertion', 'kidneys', 'bladder',
      'spine', 'arms', 'hands', 'legs', 'feet', 'genitalia']
    and not_visualised <@ array[
      'skull', 'midline_falx', 'cavum_septi_pellucidi', 'lateral_ventricles', 'cerebellum', 'cisterna_magna',
      'orbits', 'lips', 'profile', 'neck', 'lungs', 'diaphragm', 'heart_situs', 'four_chamber', 'lvot', 'rvot',
      'three_vessel_trachea', 'stomach', 'bowel', 'abdominal_wall', 'cord_insertion', 'kidneys', 'bladder',
      'spine', 'arms', 'hands', 'legs', 'feet', 'genitalia']),
  constraint anomaly_disjoint check (not (abnormal_structures && not_visualised)),
  constraint anomaly_normal_conclusion check (
    conclusion <> 'normal' or (cardinality(abnormal_structures) = 0 and cardinality(not_visualised) = 0 and cardinality(soft_markers) = 0)),
  constraint anomaly_suspected_detail check (
    conclusion <> 'anomaly_suspected' or cardinality(abnormal_structures) > 0 or coalesce(length(trim(anomalies)), 0) > 0),
  constraint anomaly_placenta_os check (placenta_os_mm is null or placenta_location is not null)
);

-- ---------------------------------------------------------------------------
-- Doppler and fetal surveillance. Centiles are entered from the reporting
-- machine/reference chart; CPR and mean UtA PI are generated; MCA PSV MoM is
-- computed against Mari et al. 2000 medians.
-- ---------------------------------------------------------------------------
create table public.fm_dopplers (
  id                   uuid primary key default gen_random_uuid(),
  fetal_assessment_id  uuid not null references public.fetal_assessments (id) on delete cascade,
  pregnancy_id         uuid not null references public.pregnancies (id),
  patient_id           uuid not null references public.patients (id),
  clinic_id            uuid not null references public.clinics (id),
  fetus_label          text not null default 'A' check (fetus_label in ('A', 'B', 'C', 'D', 'E', 'F', 'G', 'H')),
  ga_days              smallint,
  ua_pi                numeric(4, 2) check (ua_pi between 0.1 and 5),
  ua_pi_centile        numeric(4, 1) check (ua_pi_centile between 0 and 100),
  ua_edf               text check (ua_edf in ('present', 'absent', 'reversed')),
  mca_pi               numeric(4, 2) check (mca_pi between 0.1 and 5),
  mca_pi_centile       numeric(4, 1) check (mca_pi_centile between 0 and 100),
  mca_psv_cm_s         numeric(5, 1) check (mca_psv_cm_s between 5 and 150),
  mca_psv_mom          numeric(4, 2),
  cpr                  numeric(4, 2) generated always as (round(mca_pi / nullif(ua_pi, 0), 2)) stored,
  cpr_centile          numeric(4, 1) check (cpr_centile between 0 and 100),
  uta_left_pi          numeric(4, 2) check (uta_left_pi between 0.1 and 5),
  uta_right_pi         numeric(4, 2) check (uta_right_pi between 0.1 and 5),
  uta_mean_pi          numeric(4, 2) generated always as (round((uta_left_pi + uta_right_pi) / 2, 2)) stored,
  uta_pi_centile       numeric(4, 1) check (uta_pi_centile between 0 and 100),
  uta_notching         boolean,
  dv_pi                numeric(4, 2) check (dv_pi between 0.05 and 5),
  dv_pi_centile        numeric(4, 1) check (dv_pi_centile between 0 and 100),
  dv_a_wave            text check (dv_a_wave in ('positive', 'absent', 'reversed')),
  uv_pulsation         boolean,
  mvp_cm               numeric(4, 1) check (mvp_cm between 0 and 25),
  bladder_visible      boolean,
  hydrops              boolean not null default false,
  fetal_demise         boolean not null default false,
  ctg                  text check (ctg in ('normal', 'suspicious', 'pathological', 'not_done')),
  notes                text,
  recorded_by          uuid references public.profiles (id) default auth.uid(),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  unique (fetal_assessment_id, fetus_label),
  constraint doppler_has_data check (
    num_nonnulls(ua_pi, ua_edf, mca_pi, mca_psv_cm_s, uta_left_pi, uta_right_pi, dv_pi, dv_a_wave, mvp_cm, bladder_visible, ctg) > 0
    or hydrops or fetal_demise)
);

-- ---------------------------------------------------------------------------
-- Cell-free DNA screening
-- ---------------------------------------------------------------------------
create table public.fm_cfdna (
  id                  uuid primary key default gen_random_uuid(),
  patient_id          uuid not null references public.patients (id),
  pregnancy_id        uuid not null references public.pregnancies (id),
  clinic_id           uuid not null references public.clinics (id),
  sampled_on          date not null default current_date,
  ga_days             smallint,
  laboratory          text,
  result_status       text not null default 'pending' check (result_status in ('pending', 'resulted', 'failed')),
  fetal_fraction_pct  numeric(4, 1) check (fetal_fraction_pct between 0 and 60),
  t21                 text check (t21 in ('low_risk', 'high_risk', 'no_call', 'not_tested')),
  t18                 text check (t18 in ('low_risk', 'high_risk', 'no_call', 'not_tested')),
  t13                 text check (t13 in ('low_risk', 'high_risk', 'no_call', 'not_tested')),
  sex_chromosomes     text check (sex_chromosomes in ('low_risk', 'high_risk', 'no_call', 'not_tested')),
  fetal_sex           text check (fetal_sex in ('female', 'male', 'not_reported')),
  resulted_on         date,
  notes               text,
  recorded_by         uuid references public.profiles (id) default auth.uid(),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint cfdna_not_future check (sampled_on <= current_date and (resulted_on is null or resulted_on <= current_date)),
  constraint cfdna_result_after_sample check (resulted_on is null or resulted_on >= sampled_on),
  constraint cfdna_pending check (result_status <> 'pending' or (t21 is null and t18 is null and t13 is null and sex_chromosomes is null and resulted_on is null)),
  constraint cfdna_resulted check (result_status <> 'resulted' or (t21 is not null and resulted_on is not null)),
  constraint cfdna_failed check (result_status <> 'failed' or resulted_on is not null)
);

-- ---------------------------------------------------------------------------
-- Invasive procedures and fetal therapy
-- ---------------------------------------------------------------------------
create table public.fm_procedures (
  id               uuid primary key default gen_random_uuid(),
  patient_id       uuid not null references public.patients (id),
  pregnancy_id     uuid not null references public.pregnancies (id),
  clinic_id        uuid not null references public.clinics (id),
  procedure_type   text not null check (procedure_type in (
                     'cvs', 'amniocentesis', 'cordocentesis', 'intrauterine_transfusion', 'amnioreduction', 'amnioinfusion',
                     'laser_ablation', 'shunt', 'feto', 'selective_reduction', 'other')),
  performed_on     date not null default current_date,
  ga_days          smallint,
  fetus_label      text not null default 'A' check (fetus_label in ('A', 'B', 'C', 'D', 'E', 'F', 'G', 'H')),
  indication       text not null check (indication in (
                     'screen_positive', 'cfdna_high_risk', 'structural_anomaly', 'previous_aneuploidy', 'parental_rearrangement',
                     'monogenic', 'infection', 'fetal_anaemia', 'ttts', 'polyhydramnios', 'other')),
  approach         text check (approach in ('transabdominal', 'transcervical')),
  needle_gauge     smallint check (needle_gauge between 12 and 27),
  needle_passes    smallint check (needle_passes between 1 and 6),
  transplacental   boolean,
  anti_d_given     boolean,
  volume_ml        numeric(6, 1) check (volume_ml between 0 and 5000),
  pre_hb_g_dl      numeric(4, 1) check (pre_hb_g_dl between 1 and 20),
  post_hb_g_dl     numeric(4, 1) check (post_hb_g_dl between 1 and 20),
  complications    text[] not null default '{}' check (complications <@ array[
                     'none', 'bleeding', 'fluid_leak', 'membrane_rupture', 'bradycardia', 'infection', 'failed_sampling',
                     'miscarriage', 'preterm_labour', 'fetal_death']),
  tests            text[] not null default '{}' check (tests <@ array[
                     'qf_pcr', 'karyotype', 'microarray', 'exome', 'single_gene', 'infection_pcr', 'fetal_blood_count']),
  result_status    text not null default 'pending' check (result_status in ('pending', 'normal', 'abnormal', 'failed', 'not_applicable')),
  result_summary   text,
  resulted_on      date,
  operator_id      uuid references public.profiles (id) default auth.uid(),
  notes            text,
  created_by       uuid references public.profiles (id) default auth.uid(),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint proc_not_future check (performed_on <= current_date and (resulted_on is null or resulted_on <= current_date)),
  constraint proc_result_after check (resulted_on is null or resulted_on >= performed_on),
  constraint proc_result_date check (result_status in ('pending', 'not_applicable') or resulted_on is not null),
  constraint proc_pending_no_date check (result_status <> 'pending' or resulted_on is null),
  constraint proc_abnormal_summary check (result_status <> 'abnormal' or coalesce(length(trim(result_summary)), 0) > 0),
  constraint proc_transcervical_cvs check (approach <> 'transcervical' or procedure_type = 'cvs'),
  constraint proc_sampling_tests check (procedure_type not in ('cvs', 'amniocentesis', 'cordocentesis') or cardinality(tests) > 0),
  constraint proc_hb_iut check (procedure_type in ('intrauterine_transfusion', 'cordocentesis') or (pre_hb_g_dl is null and post_hb_g_dl is null)),
  constraint proc_none_exclusive check (not ('none' = any (complications)) or cardinality(complications) = 1)
);

create index fm_first_trimester_preg_idx on public.fm_first_trimester (pregnancy_id);
create index fm_anomaly_scans_preg_idx on public.fm_anomaly_scans (pregnancy_id);
create index fm_dopplers_preg_idx on public.fm_dopplers (pregnancy_id, ga_days);
create index fm_cfdna_preg_idx on public.fm_cfdna (pregnancy_id, sampled_on);
create index fm_procedures_preg_idx on public.fm_procedures (pregnancy_id, performed_on);

-- ---------------------------------------------------------------------------
-- Integrity: per-fetus scan records
-- ---------------------------------------------------------------------------
create or replace function private.fm_scan_child_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_fa       public.fetal_assessments;
  v_preg     public.pregnancies;
  v_expected text := case tg_table_name
                       when 'fm_first_trimester' then 'nt_scan'
                       when 'fm_anomaly_scans' then 'anomaly_scan'
                       else 'doppler' end;
  v_ga       smallint;
begin
  select * into v_fa from public.fetal_assessments where id = new.fetal_assessment_id;
  select * into v_preg from public.pregnancies where id = new.pregnancy_id;
  if v_fa.id is null or v_preg.id is null or v_fa.patient_id <> new.patient_id or v_preg.patient_id <> new.patient_id
     or (v_fa.pregnancy_id is not null and v_fa.pregnancy_id <> new.pregnancy_id) then
    raise exception 'Record must match its scan, pregnancy and patient' using errcode = '23514';
  end if;
  if v_fa.assessment_type <> v_expected then
    raise exception 'This record requires a % scan', v_expected using errcode = '23514';
  end if;
  if ascii(new.fetus_label) - 64 > v_preg.plurality then
    raise exception 'Fetus % does not exist in this pregnancy (plurality %)', new.fetus_label, v_preg.plurality using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' then
    if new.fetal_assessment_id <> old.fetal_assessment_id or new.pregnancy_id <> old.pregnancy_id
       or new.patient_id <> old.patient_id or new.fetus_label <> old.fetus_label then
      raise exception 'Record links are immutable' using errcode = '42501';
    end if;
  elsif not private.is_server_context() then
    new := jsonb_populate_record(new, jsonb_build_object('recorded_by', auth.uid()));
  end if;
  v_ga := private.pregnancy_ga_days(new.pregnancy_id, v_fa.performed_at::date);
  new := jsonb_populate_record(new, jsonb_build_object('ga_days', v_ga));
  if tg_table_name = 'fm_dopplers' then
    -- Mari G et al. NEJM 2000: median MCA PSV = exp(2.31 + 0.046 × GA weeks)
    new := jsonb_populate_record(new, jsonb_build_object('mca_psv_mom',
      case when (to_jsonb(new) ->> 'mca_psv_cm_s') is not null and v_ga between 112 and 280
           then round((to_jsonb(new) ->> 'mca_psv_cm_s')::numeric / exp(2.31 + 0.046 * v_ga / 7.0)::numeric, 2) end));
  end if;
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['fm_first_trimester', 'fm_anomaly_scans', 'fm_dopplers'] loop
    execute format('create trigger %I before insert or update on public.%I for each row execute function private.fm_scan_child_rules()', t || '_rules', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- Integrity: cfDNA and procedures
-- ---------------------------------------------------------------------------
create or replace function private.fm_pregnancy_record_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_preg public.pregnancies;
  v_date date := coalesce((to_jsonb(new) ->> 'performed_on')::date, (to_jsonb(new) ->> 'sampled_on')::date);
begin
  select * into v_preg from public.pregnancies where id = new.pregnancy_id;
  if v_preg.id is null or v_preg.patient_id <> new.patient_id then
    raise exception 'Record must belong to a pregnancy of the same patient' using errcode = '23514';
  end if;
  if tg_table_name = 'fm_procedures' and ascii(to_jsonb(new) ->> 'fetus_label') - 64 > v_preg.plurality then
    raise exception 'Fetus does not exist in this pregnancy' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' then
    if new.pregnancy_id <> old.pregnancy_id or new.patient_id <> old.patient_id then
      raise exception 'Record links are immutable' using errcode = '42501';
    end if;
  elsif not private.is_server_context() then
    if tg_table_name = 'fm_procedures' then
      new := jsonb_populate_record(new, jsonb_build_object('created_by', auth.uid(),
        'operator_id', coalesce(to_jsonb(new) ->> 'operator_id', auth.uid()::text)));
    else
      new := jsonb_populate_record(new, jsonb_build_object('recorded_by', auth.uid()));
    end if;
  end if;
  new := jsonb_populate_record(new, jsonb_build_object('ga_days', private.pregnancy_ga_days(new.pregnancy_id, v_date)));
  return new;
end;
$$;

create trigger fm_cfdna_rules before insert or update on public.fm_cfdna
  for each row execute function private.fm_pregnancy_record_rules();
create trigger fm_procedures_rules before insert or update on public.fm_procedures
  for each row execute function private.fm_pregnancy_record_rules();

-- Tag the patient with fetal medicine when any record is created.
create or replace function private.fm_tag_patient()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.patients
     set specialties = array_append(specialties, 'fetal_medicine'::public.specialty)
   where id = new.patient_id and not ('fetal_medicine' = any (specialties));
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['fm_first_trimester', 'fm_anomaly_scans', 'fm_dopplers', 'fm_cfdna', 'fm_procedures'] loop
    execute format('create trigger %I before update on public.%I for each row execute function private.touch_updated_at()', t || '_touch', t);
    execute format('create trigger %I after insert on public.%I for each row execute function private.fm_tag_patient()', t || '_tag', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update on public.%I to authenticated', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function private.audit_row_change()', t || '_audit', t);
    execute format($p$create policy %I on public.%I for select to authenticated using (private.can(patient_id, 'clinical.read'))$p$, t || '_select', t);
    execute format($p$create policy %I on public.%I for insert to authenticated
      with check (private.can(patient_id, 'clinical.write') and private.is_clinic_member(clinic_id))$p$, t || '_insert', t);
    execute format($p$create policy %I on public.%I for update to authenticated
      using (private.can(patient_id, 'clinical.write')) with check (private.can(patient_id, 'clinical.write'))$p$, t || '_update', t);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- RPC: scan header + per-fetus records in one transaction
--   p_type     'nt_scan' | 'anomaly_scan' | 'doppler'
--   p_scan     { performed_at?, impression?, clinic_id? }
--   p_fetuses  [ { fetus_label, ...type-specific fields } ]
-- ---------------------------------------------------------------------------
create or replace function public.record_fm_scan(
  p_pregnancy_id  uuid,
  p_type          text,
  p_scan          jsonb,
  p_fetuses       jsonb
)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_preg   public.pregnancies;
  v_clinic uuid;
  v_at     timestamptz := coalesce((p_scan ->> 'performed_at')::timestamptz, now());
  v_id     uuid;
  v_f      jsonb;
  v_ft     public.fm_first_trimester;
  v_an     public.fm_anomaly_scans;
  v_dp     public.fm_dopplers;
begin
  if p_type not in ('nt_scan', 'anomaly_scan', 'doppler') then
    raise exception 'Unknown fetal medicine scan type %', p_type using errcode = '22023';
  end if;
  select * into v_preg from public.pregnancies where id = p_pregnancy_id;
  if not found then
    raise exception 'Pregnancy not found' using errcode = 'P0002';
  end if;
  if v_at > now() then
    raise exception 'Scan date cannot be in the future' using errcode = '22023';
  end if;
  if jsonb_typeof(p_fetuses) <> 'array' or jsonb_array_length(p_fetuses) = 0
     or jsonb_array_length(p_fetuses) > v_preg.plurality then
    raise exception 'Provide between 1 and % fetus records', v_preg.plurality using errcode = '22023';
  end if;
  v_clinic := coalesce(nullif(p_scan ->> 'clinic_id', '')::uuid, v_preg.clinic_id);

  insert into public.fetal_assessments
    (patient_id, pregnancy_id, clinic_id, assessment_type, performed_at, gestational_age_days, fetus_number, impression, findings)
  values
    (v_preg.patient_id, v_preg.id, v_clinic, p_type, v_at, private.pregnancy_ga_days(v_preg.id, v_at::date),
     jsonb_array_length(p_fetuses), p_scan ->> 'impression', '{}'::jsonb)
  returning id into v_id;

  for v_f in select * from jsonb_array_elements(p_fetuses) loop
    if p_type = 'nt_scan' then
      v_ft := jsonb_populate_record(null::public.fm_first_trimester, v_f);
      insert into public.fm_first_trimester
        (fetal_assessment_id, pregnancy_id, patient_id, clinic_id, fetus_label, crl_mm, nt_mm, nasal_bone, dv_a_wave,
         tricuspid_regurgitation, fhr, papp_a_mom, free_bhcg_mom, risk_t21, risk_t18, risk_t13, risk_method, risk_software,
         early_anatomy, notes)
      values
        (v_id, v_preg.id, v_preg.patient_id, v_clinic, coalesce(v_ft.fetus_label, 'A'), v_ft.crl_mm, v_ft.nt_mm, v_ft.nasal_bone,
         v_ft.dv_a_wave, v_ft.tricuspid_regurgitation, v_ft.fhr, v_ft.papp_a_mom, v_ft.free_bhcg_mom, v_ft.risk_t21, v_ft.risk_t18,
         v_ft.risk_t13, v_ft.risk_method, v_ft.risk_software, v_ft.early_anatomy, v_ft.notes);
    elsif p_type = 'anomaly_scan' then
      v_an := jsonb_populate_record(null::public.fm_anomaly_scans, v_f);
      insert into public.fm_anomaly_scans
        (fetal_assessment_id, pregnancy_id, patient_id, clinic_id, fetus_label, abnormal_structures, not_visualised, atrium_mm,
         tcd_mm, cisterna_magna_mm, nuchal_fold_mm, renal_pelvis_mm, cervical_length_mm, placenta_location, placenta_os_mm,
         cord_vessels, amniotic_fluid, soft_markers, fetal_sex, anomalies, conclusion, notes)
      values
        (v_id, v_preg.id, v_preg.patient_id, v_clinic, coalesce(v_an.fetus_label, 'A'), coalesce(v_an.abnormal_structures, '{}'),
         coalesce(v_an.not_visualised, '{}'), v_an.atrium_mm, v_an.tcd_mm, v_an.cisterna_magna_mm, v_an.nuchal_fold_mm,
         v_an.renal_pelvis_mm, v_an.cervical_length_mm, v_an.placenta_location, v_an.placenta_os_mm, v_an.cord_vessels,
         v_an.amniotic_fluid, coalesce(v_an.soft_markers, '{}'), v_an.fetal_sex, v_an.anomalies, coalesce(v_an.conclusion, 'normal'), v_an.notes);
    else
      v_dp := jsonb_populate_record(null::public.fm_dopplers, v_f);
      insert into public.fm_dopplers
        (fetal_assessment_id, pregnancy_id, patient_id, clinic_id, fetus_label, ua_pi, ua_pi_centile, ua_edf, mca_pi, mca_pi_centile,
         mca_psv_cm_s, cpr_centile, uta_left_pi, uta_right_pi, uta_pi_centile, uta_notching, dv_pi, dv_pi_centile, dv_a_wave,
         uv_pulsation, mvp_cm, bladder_visible, hydrops, fetal_demise, ctg, notes)
      values
        (v_id, v_preg.id, v_preg.patient_id, v_clinic, coalesce(v_dp.fetus_label, 'A'), v_dp.ua_pi, v_dp.ua_pi_centile, v_dp.ua_edf,
         v_dp.mca_pi, v_dp.mca_pi_centile, v_dp.mca_psv_cm_s, v_dp.cpr_centile, v_dp.uta_left_pi, v_dp.uta_right_pi,
         v_dp.uta_pi_centile, v_dp.uta_notching, v_dp.dv_pi, v_dp.dv_pi_centile, v_dp.dv_a_wave, v_dp.uv_pulsation, v_dp.mvp_cm,
         v_dp.bladder_visible, coalesce(v_dp.hydrops, false), coalesce(v_dp.fetal_demise, false), v_dp.ctg, v_dp.notes);
    end if;
  end loop;

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Worklist: active pregnancies with any fetal medicine record or tag
-- ---------------------------------------------------------------------------
create view public.fm_worklist
with (security_invoker = true)
as
select
  g.id as pregnancy_id, g.patient_id, g.clinic_id, g.plurality, g.chorionicity, g.edd, g.lmp, g.cycle_length_days,
  private.pregnancy_ga_days(g.id, current_date) as ga_days,
  p.mrn, p.first_name_en, p.last_name_en, p.first_name_ar, p.last_name_ar, p.date_of_birth, p.rh_factor,
  ft.risk_t21 as last_risk_t21, ft.risk_t18 as last_risk_t18, ft.risk_t13 as last_risk_t13, ft.nt_mm as last_nt_mm,
  cf.result_status as cfdna_status, cf.t21 as cfdna_t21, cf.t18 as cfdna_t18, cf.t13 as cfdna_t13,
  an.conclusion as anomaly_conclusion, an.performed_at as anomaly_at,
  dp.performed_at as last_doppler_at, dp.ua_edf as last_ua_edf, dp.dv_a_wave as last_dv_a_wave,
  dp.mca_psv_mom as last_mca_psv_mom, dp.cpr as last_cpr, dp.hydrops as last_hydrops, dp.cpr_low as last_cpr_low,
  dp.ua_pi_high as last_ua_pi_high, dp.mvp_min as last_mvp_min, dp.mvp_max as last_mvp_max, dp.bladder_absent as last_bladder_absent,
  (select count(*) from public.fm_procedures pr where pr.pregnancy_id = g.id and pr.result_status = 'pending')::int as pending_procedures,
  (select max(fa.performed_at) from public.fetal_assessments fa where fa.pregnancy_id = g.id) as last_scan_at
from public.pregnancies g
join public.patients p on p.id = g.patient_id and p.deleted_at is null
left join lateral (
  select min(x.risk_t21) as risk_t21, min(x.risk_t18) as risk_t18, min(x.risk_t13) as risk_t13, max(x.nt_mm) as nt_mm
  from public.fm_first_trimester x
  where x.fetal_assessment_id = (select f.fetal_assessment_id from public.fm_first_trimester f
                                   join public.fetal_assessments a on a.id = f.fetal_assessment_id
                                  where f.pregnancy_id = g.id order by a.performed_at desc limit 1)
) ft on true
left join lateral (
  select * from public.fm_cfdna c where c.pregnancy_id = g.id order by c.sampled_on desc, c.created_at desc limit 1
) cf on true
left join lateral (
  select a.performed_at,
         (array['normal', 'soft_markers', 'incomplete', 'anomaly_suspected'])[max(array_position(
           array['normal', 'soft_markers', 'incomplete', 'anomaly_suspected'], s.conclusion))] as conclusion
  from public.fm_anomaly_scans s join public.fetal_assessments a on a.id = s.fetal_assessment_id
  where s.pregnancy_id = g.id
  group by a.id, a.performed_at order by a.performed_at desc limit 1
) an on true
left join lateral (
  select a.performed_at,
         (array['present', 'absent', 'reversed'])[max(array_position(array['present', 'absent', 'reversed'], d.ua_edf))] as ua_edf,
         (array['positive', 'absent', 'reversed'])[max(array_position(array['positive', 'absent', 'reversed'], d.dv_a_wave))] as dv_a_wave,
         max(d.mca_psv_mom) as mca_psv_mom, min(d.cpr) as cpr, bool_or(d.hydrops) as hydrops,
         -- CPR centile takes precedence over the CPR < 1 fallback (as in the application rules)
         coalesce(bool_or(case when d.cpr_centile is not null then d.cpr_centile < 5 else d.cpr < 1 end), false) as cpr_low,
         coalesce(bool_or(d.ua_pi_centile > 95), false) as ua_pi_high,
         min(d.mvp_cm) as mvp_min, max(d.mvp_cm) as mvp_max, coalesce(bool_or(d.bladder_visible = false), false) as bladder_absent
  from public.fm_dopplers d join public.fetal_assessments a on a.id = d.fetal_assessment_id
  where d.pregnancy_id = g.id
  group by a.id, a.performed_at order by a.performed_at desc limit 1
) dp on true
where g.status = 'active'
  and ('fetal_medicine' = any (p.specialties)
       or exists (select 1 from public.fm_cfdna c where c.pregnancy_id = g.id)
       or exists (select 1 from public.fm_procedures pr where pr.pregnancy_id = g.id));

grant select on public.fm_worklist to authenticated;
revoke all on public.fm_worklist from anon;

revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;
revoke execute on function public.record_fm_scan(uuid, text, jsonb, jsonb) from public, anon;
grant execute on function public.record_fm_scan(uuid, text, jsonb, jsonb) to authenticated;

-- >>> 20261126000013_staff_access.sql
-- =============================================================================
-- 0013  Staff access
--   * Per-membership permission overrides (granted / revoked on top of the role)
--   * Specialty scope: a membership can be limited to some specialties; clinic
--     access to a patient then requires an overlapping specialty
--   * Code-only sign-in: each person has a public 4-character login handle; the
--     secret part of their code is their (bcrypt-hashed) Supabase password.
--     Server-only RPCs support lock-out and session revocation for the
--     `code-login` / `staff-admin` Edge Functions.
-- =============================================================================

-- Login handle (public half of a login code)
alter table public.profiles
  add column login_handle   text unique check (login_handle ~ '^[2-9A-HJKMNP-Z]{4}$'),
  add column code_issued_at timestamptz;

-- ---------------------------------------------------------------------------
-- Memberships: overrides and scope
-- ---------------------------------------------------------------------------
alter table public.clinic_memberships
  add column granted_permissions text[] not null default '{}',
  add column revoked_permissions text[] not null default '{}',
  add column specialties public.specialty[],            -- null = all specialties
  add constraint membership_specialties_nonempty check (specialties is null or cardinality(specialties) > 0),
  add constraint membership_overrides_disjoint check (not (granted_permissions && revoked_permissions));

create or replace function private.membership_override_rules()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_unknown text;
begin
  select x into v_unknown
  from unnest(new.granted_permissions || new.revoked_permissions) x
  where not exists (select 1 from public.permissions p where p.code = x)
  limit 1;
  if v_unknown is not null then
    raise exception 'Unknown permission %', v_unknown using errcode = '22023';
  end if;
  -- normalise (sorted, unique)
  new.granted_permissions := coalesce((select array_agg(distinct x order by x) from unnest(new.granted_permissions) x), '{}');
  new.revoked_permissions := coalesce((select array_agg(distinct x order by x) from unnest(new.revoked_permissions) x), '{}');
  if new.specialties is not null then
    new.specialties := (select array_agg(distinct x order by x) from unnest(new.specialties) x);
  end if;
  -- administrative permissions can only be added by a super administrator
  if not private.is_server_context() and not private.is_super_admin()
     and new.granted_permissions && array['admin.users', 'admin.clinic', 'audit.read']
     and (tg_op = 'INSERT' or new.granted_permissions is distinct from old.granted_permissions) then
    raise exception 'Only a super administrator can grant administrative permissions' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger clinic_memberships_overrides before insert or update on public.clinic_memberships
  for each row execute function private.membership_override_rules();

-- Effective permissions of a membership: role ∪ granted − revoked
create or replace function private.effective_permissions(p_role public.app_role, p_granted text[], p_revoked text[])
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(distinct p order by p), '{}')
  from (
    select rp.permission as p from public.role_permissions rp where rp.role = p_role
    union
    select unnest(p_granted)
  ) x
  where not (p = any (p_revoked));
$$;

create or replace function private.has_permission(p_clinic uuid, p_perm text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_super_admin() or exists (
    select 1
    from public.clinic_memberships m
    join public.profiles pr on pr.id = m.user_id and pr.is_active
    join public.clinics c   on c.id = m.clinic_id and c.is_active
    where m.user_id = auth.uid()
      and m.clinic_id = p_clinic
      and m.is_active
      and not (p_perm = any (m.revoked_permissions))
      and (p_perm = any (m.granted_permissions)
           or exists (select 1 from public.role_permissions rp where rp.role = m.role and rp.permission = p_perm))
  );
$$;

create or replace function private.has_permission_any(p_perm text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_super_admin() or exists (
    select 1
    from public.clinic_memberships m
    join public.profiles pr on pr.id = m.user_id and pr.is_active
    join public.clinics c   on c.id = m.clinic_id and c.is_active
    where m.user_id = auth.uid()
      and m.is_active
      and not (p_perm = any (m.revoked_permissions))
      and (p_perm = any (m.granted_permissions)
           or exists (select 1 from public.role_permissions rp where rp.role = m.role and rp.permission = p_perm))
  );
$$;

-- Does the caller's membership in `p_clinic` cover the patient's specialties?
-- A patient without specialties (new registration) is in everyone's scope.
create or replace function private.scope_allows(p_clinic uuid, p_patient uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_super_admin() or exists (
    select 1 from public.clinic_memberships m
    where m.user_id = auth.uid() and m.clinic_id = p_clinic and m.is_active
      and (m.specialties is null
           or coalesce((select cardinality(p.specialties) = 0 or p.specialties && m.specialties
                        from public.patients p where p.id = p_patient), true))
  );
$$;

-- Patient access: the clinic routes (2 and 5) now also require specialty scope.
-- Primary physicians and explicit personal grants are not limited by scope.
create or replace function private.patient_can(
  p_patient_id  uuid,
  p_clinic      uuid,
  p_visibility  public.record_visibility,
  p_primary     uuid,
  p_perm        text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := auth.uid();
  v_is_read  boolean := p_perm like '%.read';
begin
  if v_uid is null then
    return false;
  end if;

  -- 1. super admin (non-private records)
  if p_visibility = 'clinic' and private.is_super_admin() then
    return true;
  end if;

  -- 2. owning clinic, within the member's specialty scope
  if p_visibility = 'clinic' and private.has_permission(p_clinic, p_perm) and private.scope_allows(p_clinic, p_patient_id) then
    return true;
  end if;

  -- 3. primary physician
  if p_primary = v_uid and private.has_permission_any(p_perm) then
    return true;
  end if;

  -- 4. explicit user grant
  if exists (
    select 1 from public.patient_access_grants g
    where g.patient_id = p_patient_id
      and g.grantee_user_id = v_uid
      and g.revoked_at is null
      and (g.expires_at is null or g.expires_at > now())
      and (v_is_read or g.access_level = 'write')
  ) and (private.has_permission_any(p_perm) or private.is_super_admin()) then
    return true;
  end if;

  -- 5. clinic grant (only for clinic-visibility records), within scope
  if p_visibility = 'clinic' and exists (
    select 1 from public.patient_access_grants g
    where g.patient_id = p_patient_id
      and g.grantee_clinic_id is not null
      and g.revoked_at is null
      and (g.expires_at is null or g.expires_at > now())
      and (v_is_read or g.access_level = 'write')
      and private.has_permission(g.grantee_clinic_id, p_perm)
      and private.scope_allows(g.grantee_clinic_id, p_patient_id)
  ) then
    return true;
  end if;

  return false;
end;
$$;

-- Access summary for the UI: effective permissions and specialty scope.
create or replace function public.get_my_access()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'user_id', p.id,
    'is_super_admin', p.is_super_admin and p.is_active,
    'is_active', p.is_active,
    'login_handle', p.login_handle,
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'clinic_id', c.id,
        'clinic_code', c.code,
        'clinic_name_en', c.name_en,
        'clinic_name_ar', c.name_ar,
        'role', m.role,
        'permissions', to_jsonb(private.effective_permissions(m.role, m.granted_permissions, m.revoked_permissions)),
        'specialties', to_jsonb(m.specialties)
      ) order by c.name_en)
      from public.clinic_memberships m
      join public.clinics c on c.id = m.clinic_id and c.is_active
      where m.user_id = p.id and m.is_active
    ), '[]'::jsonb)
  )
  from public.profiles p
  where p.id = auth.uid();
$$;

-- ---------------------------------------------------------------------------
-- Login codes
-- ---------------------------------------------------------------------------
-- login_handle and code_issued_at are written only by the server functions
create or replace function private.protect_login_fields()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not private.is_server_context()
     and (new.login_handle is distinct from old.login_handle or new.code_issued_at is distinct from old.code_issued_at) then
    raise exception 'Login codes are managed by the server' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger profiles_protect_login before update on public.profiles
  for each row execute function private.protect_login_fields();

alter table public.audit_log drop constraint audit_log_action_check;
alter table public.audit_log add constraint audit_log_action_check check (action in (
  'INSERT', 'UPDATE', 'DELETE', 'VIEW', 'DOWNLOAD', 'PRINT', 'EXPORT', 'EMERGENCY_ACCESS', 'RESEARCH_QUERY',
  'SIGN_IN', 'SIGN_OUT', 'SIGN_IN_FAILED', 'CODE_ISSUED'));

-- Failed attempts per handle (not exposed to clients).
create table private.code_login_attempts (
  handle        text primary key,
  failures      smallint not null default 0,
  locked_until  timestamptz,
  last_attempt  timestamptz not null default now()
);

-- Server-only: resolve a handle for sign-in.
create or replace function public.code_login_lookup(p_handle text)
returns table (user_id uuid, email text, is_active boolean, locked_until timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select p.id, u.email::text, p.is_active,
         (select a.locked_until from private.code_login_attempts a where a.handle = upper(p_handle) and a.locked_until > now())
  from public.profiles p
  join auth.users u on u.id = p.id
  where p.login_handle = upper(p_handle)
  union all
  select null, null, null, a.locked_until
  from private.code_login_attempts a
  where a.handle = upper(p_handle) and a.locked_until > now()
    and not exists (select 1 from public.profiles p where p.login_handle = upper(p_handle));
$$;

-- Server-only: record an attempt. 5 consecutive failures lock the handle for 15 minutes.
create or replace function public.code_login_record(p_handle text, p_success boolean, p_context jsonb default '{}'::jsonb)
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handle text := upper(p_handle);
  v_user   uuid := (select id from public.profiles where login_handle = v_handle);
  v_row    private.code_login_attempts;
begin
  if p_success then
    delete from private.code_login_attempts where handle = v_handle;
    insert into public.audit_log (actor_id, action, context) values (v_user, 'SIGN_IN', p_context || jsonb_build_object('via', 'login_code'));
    return null;
  end if;
  insert into private.code_login_attempts as a (handle, failures, last_attempt)
  values (v_handle, 1, now())
  on conflict (handle) do update
    set failures = case when a.locked_until is not null and a.locked_until <= now() then 1 else a.failures + 1 end,
        locked_until = case when a.locked_until is not null and a.locked_until <= now() then null else a.locked_until end,
        last_attempt = now()
  returning * into v_row;
  if v_row.failures >= 5 and v_row.locked_until is null then
    update private.code_login_attempts set locked_until = now() + interval '15 minutes' where handle = v_handle
    returning * into v_row;
  end if;
  insert into public.audit_log (actor_id, action, context)
  values (v_user, 'SIGN_IN_FAILED', p_context || jsonb_build_object('via', 'login_code', 'handle', v_handle, 'failures', v_row.failures));
  return v_row.locked_until;
end;
$$;

-- Server-only: end a user's sessions (after a code reset), optionally keeping one.
create or replace function public.admin_revoke_sessions(p_user uuid, p_keep uuid default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_n integer;
begin
  delete from auth.sessions where user_id = p_user and (p_keep is null or id <> p_keep);
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

-- Full-data export (backup) by a super administrator is recorded in the audit log.
create or replace function public.log_data_export(p_context jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_super_admin() then
    raise exception 'Only a super administrator can export all data' using errcode = '42501';
  end if;
  insert into public.audit_log (actor_id, action, context) values (auth.uid(), 'EXPORT', coalesce(p_context, '{}'::jsonb) || '{"scope": "all"}');
end;
$$;
revoke execute on function public.log_data_export(jsonb) from public, anon;
grant execute on function public.log_data_export(jsonb) to authenticated;

revoke execute on function public.code_login_lookup(text) from public, anon, authenticated;
revoke execute on function public.code_login_record(text, boolean, jsonb) from public, anon, authenticated;
revoke execute on function public.admin_revoke_sessions(uuid, uuid) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.code_login_lookup(text) to service_role;
    grant execute on function public.code_login_record(text, boolean, jsonb) to service_role;
    grant execute on function public.admin_revoke_sessions(uuid, uuid) to service_role;
  end if;
end;
$$;

revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;
